tf_code:
// File: dns.tf
resource "aws_route53_zone" "private" {
    name = var.internal_domain

    vpc {
        vpc_id = aws_vpc.main.id
    }
}

resource "aws_vpc_dhcp_options" "domains" {
    domain_name = var.internal_domain
    domain_name_servers = var.dns_resolvers
}

resource "aws_vpc_dhcp_options_association" "domains" {
    vpc_id = aws_vpc.main.id
    dhcp_options_id = aws_vpc_dhcp_options.domains.id
}

// File: nacls.tf
resource "aws_network_acl" "sandbox" {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.sandbox.id]

    ingress {
        protocol = "tcp"
        rule_no = 101
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
    ingress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 32768
        to_port = 65535
    }
    egress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
}

resource "aws_network_acl" "web" {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.web.id]

    ingress {
        protocol = "tcp"
        rule_no = 101
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 22
        to_port = 22
    }
    ingress {
        protocol = "tcp"
        rule_no = 102
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 80
        to_port = 80
    }
    ingress {
        protocol = "tcp"
        rule_no = 103
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 443
        to_port = 443
    }
    ingress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 32768
        to_port = 65535
    }
    egress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
}

resource "aws_network_acl" "database" {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.database.id]

    ingress {
        protocol = "tcp"
        rule_no = 100
        action = "allow"
        cidr_block = var.web_subnet_cidr
        from_port = 0
        to_port = 65535
    }
    egress {
        protocol = "tcp"
        rule_no = 999
        action = "allow"
        cidr_block = var.web_subnet_cidr
        from_port = 0
        to_port = 65535
    }
    ingress {
        protocol = "tcp"
        rule_no = 200
        action = "allow"
        cidr_block = var.gameserver_subnet_cidr
        from_port = 0
        to_port = 65535
    }
    egress {
        protocol = "tcp"
        rule_no = 200
        action = "allow"
        cidr_block = var.gameserver_subnet_cidr
        from_port = 0
        to_port = 65535
    }
}

resource "aws_network_acl" "gameserver" {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.gameserver.id]

    ingress {
        protocol = "tcp"
        rule_no = 101
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 22
        to_port = 22
    }
    ingress {
        protocol = "tcp"
        rule_no = 200
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 27015
        to_port = 27015
    }
    ingress {
        protocol = "tcp"
        rule_no = 201
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 27020
        to_port = 27020
    }
    ingress {
        protocol = "udp"
        rule_no = 202
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 27015
        to_port = 27015
    }
    ingress {
        protocol = "udp"
        rule_no = 203
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 27020
        to_port = 27020
    }
    ingress {
        protocol = "tcp"
        rule_no = 998
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 32768
        to_port = 65535
    }
    ingress {
        protocol = "udp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 32768
        to_port = 65535
    }

    egress {
        protocol = "tcp"
        rule_no = 998
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
    egress {
        protocol = "udp"
        rule_no = 999
        action = "allow"
        cidr_block = "0.0.0.0/0"
        from_port = 0
        to_port = 65535
    }
}

// File: outputs.tf
output "vpc_id" {
    value = aws_vpc.main.id
}

output "reserved_subnet_id" {
    value = aws_subnet.reserved.id
}

output "sandbox_subnet_id" {
    value = aws_subnet.sandbox.id
}

output "web_subnet_id" {
    value = aws_subnet.web.id
}

output "database_subnet_id" {
    value = aws_subnet.database.id
}

output "gameserver_subnet_id" {
    value = aws_subnet.gameserver.id
}

output "ssh_securitygroup_id" {
    value = aws_security_group.home_ssh.id
}

output "internal_dns_zone_id" {
    value = aws_route53_zone.private.id
}

// File: security_groups.tf
resource "aws_security_group" "home_ssh" {
    name = "Home SSH"
    description = "SSH from home"
    vpc_id = aws_vpc.main.id

    ingress {
        from_port = 22
        to_port = 22
        protocol = "tcp"
        cidr_blocks =  var.ssh_ip_addrs
        self = true
    }

    egress {
        from_port   = 0
        to_port     = 0
        protocol    = "-1"
        cidr_blocks = ["0.0.0.0/0"]
    }

    tags = {
        Name = "Home SSH"
    }
}

resource "aws_security_group" "packer_ssh" {
    name = "Packer SSH"
    description = "SSH for Packer"
    vpc_id = aws_vpc.main.id

    ingress {
        from_port = 22
        to_port = 22
        protocol = "tcp"
        cidr_blocks = ["0.0.0.0/0"]
        self = true
    }

    egress {
        from_port   = 0
        to_port     = 0
        protocol    = "-1"
        cidr_blocks = ["0.0.0.0/0"]
    }

    tags = {
        Name = "Packer SSH"
    }
}

// File: subnets.tf
# Reserved for use by NAT's and other appliances
resource "aws_subnet" "reserved" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.reserved_subnet_cidr
    map_public_ip_on_launch  = false

    tags = {
        Name = "reserved"
    }
}
resource "aws_route_table" "reserved" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "reserved" {
    subnet_id = aws_subnet.reserved.id
    route_table_id = aws_route_table.reserved.id
}

# Used for builds or otherwise unimportant things
# Not able to access other subnets
resource "aws_subnet" "sandbox" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.sandbox_subnet_cidr
    map_public_ip_on_launch = true

    tags = {
        Name = "sandbox"
    }
}
resource "aws_route_table" "sandbox" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "sandbox" {
    subnet_id = aws_subnet.sandbox.id
    route_table_id = aws_route_table.sandbox.id
}

# Used for web applications
# Bot software
# Frontends
resource "aws_subnet" "web" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.web_subnet_cidr
    map_public_ip_on_launch = true

    tags = {
        Name = "web"
    }
}
resource "aws_route_table" "web" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "web" {
    subnet_id = aws_subnet.web.id
    route_table_id = aws_route_table.web.id
}

# Used to back web and gameserver resources
# Not accessiable from the internet
resource "aws_subnet" "database" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.database_subnet_cidr
    map_public_ip_on_launch = false

    tags = {
        Name = "database"
    }
}
resource "aws_route_table" "database" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "database" {
    subnet_id = aws_subnet.database.id
    route_table_id = aws_route_table.database.id
}

# Used to house all the gameservers
resource "aws_subnet" "gameserver" {
    vpc_id = aws_vpc.main.id
    cidr_block = var.gameserver_subnet_cidr
    map_public_ip_on_launch = true

    tags = {
        Name = "gameserver"
    }
}
resource "aws_route_table" "gameserver" {
    vpc_id = aws_vpc.main.id

    route {
        cidr_block = "0.0.0.0/0"
        gateway_id = aws_internet_gateway.main.id
    }
}
resource "aws_route_table_association" "gameserver" {
    subnet_id = aws_subnet.gameserver.id
    route_table_id = aws_route_table.gameserver.id
}

// File: variables.tf
variable "vpc_cidr" {
    type = string
    default = "10.0.0.0/16"
}

variable "internal_domain" {
    type = string
    default = "internal"
}

variable "dns_resolvers" {
    type = list
    default = ["10.0.0.2", "8.8.8.8"]
}

variable "ssh_ip_addrs" {
    type = list
    default = ["0.0.0.0/0"]
}

variable "reserved_subnet_cidr" {
    type = string
    default = "10.0.0.0/24"
}

variable "sandbox_subnet_cidr" {
    type = string
    default = "10.0.1.0/24"
}

variable "web_subnet_cidr" {
    type = string
    default = "10.0.2.0/24"
}

variable "database_subnet_cidr" {
    type = string
    default = "10.0.3.0/24"
}

variable "gameserver_subnet_cidr" {
    type = string
    default = "10.0.4.0/22"
}

// File: vpc.tf
resource "aws_vpc" "main" {
    cidr_block = var.vpc_cidr

    enable_dns_support = true
    enable_dns_hostnames = true

    tags = {
        Name = "main"
    }
}

resource "aws_internet_gateway" "main" {
    vpc_id = aws_vpc.main.id

    tags = {
        Name = "ig"
    }
}

// File: main.tf
resource "random_pet" "sftp" {
  length    = 2
  separator = "-"
}

locals {
  name = var.name == null ? random_pet.sftp.id : var.name
}

resource "aws_iam_role" "logging" {
  count = var.logging_role == null ? 1 : 0
  name  = "${local.name}-transfer-logging"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "transfer.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "logging" {
  count      = var.logging_role == null ? 1 : 0
  role       = join(",", aws_iam_role.logging[*].name)
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

resource "aws_iam_role" "auth" {
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0
  name  = "${local.name}-api-gateway-auth"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "transfer.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "auth" {
  # checkov:skip=CKV_AWS_355: "*" in resource is required for this policy
  # checkov:skip=CKV_AWS_290: Write access required for this policy
  count = var.identity_provider_type == "API_GATEWAY" ? 1 : 0
  name  = "${local.name}-api-gateway-auth"
  role  = join(",", aws_iam_role.auth[*].id)

  policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "*"
    }
  ]
}
POLICY
}

resource "aws_transfer_server" "public" {
  # checkov:skip=CKV_AWS_164: Exposing server publicly depends on user
  count                            = var.sftp_type == "PUBLIC" ? 1 : 0
  endpoint_type                    = var.sftp_type
  domain                           = var.storage_type
  protocols                        = var.protocols
  certificate                      = var.certificate_arn
  identity_provider_type           = var.identity_provider_type
  url                              = var.api_gw_url
  invocation_role                  = var.invocation_role
  directory_id                     = var.directory_id
  function                         = var.function_arn
  logging_role                     = var.logging_role == null ? join(",", aws_iam_role.logging[*].arn) : var.logging_role
  force_destroy                    = var.force_destroy
  security_policy_name             = var.security_policy_name
  host_key                         = var.host_key
  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner
  structured_log_destinations      = var.cloudwatch_log_group_arns

  dynamic "protocol_details" {
    for_each = var.as2_transports == null && var.passive_ip == null && var.set_stat_option == null && var.tls_session_resumption_mode == null ? [] : [0]
    content {
      as2_transports              = var.as2_transports
      passive_ip                  = var.passive_ip
      set_stat_option             = var.set_stat_option
      tls_session_resumption_mode = var.tls_session_resumption_mode
    }
  }

  tags = merge({
    Name = local.name
  }, var.tags)
}

resource "aws_security_group" "sftp_vpc" {
  # checkov:skip=CKV2_AWS_5: Associated to SFTP server
  # checkov:skip=CKV_AWS_24: Port 22 open required to the world
  count       = var.sftp_type == "VPC" && lookup(var.endpoint_details, "security_group_ids", null) == null ? 1 : 0
  name        = "${local.name}-sftp-vpc"
  description = "Security group for SFTP VPC"
  vpc_id      = lookup(var.endpoint_details, "vpc_id")

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow connections from everywhere on port 22"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound connections"
  }
}

resource "aws_eip" "sftp_vpc" {
  # checkov:skip=CKV2_AWS_19: EIP will be attached to SFTP server
  count  = var.sftp_type == "VPC" && lookup(var.endpoint_details, "address_allocation_ids", null) == null ? length(lookup(var.endpoint_details, "subnet_ids")) : 0
  domain = "vpc"
  tags   = var.tags
}

resource "aws_transfer_server" "vpc" {
  # checkov:skip=CKV_AWS_164: Exposing server publicly depends on user
  count         = var.sftp_type != "PUBLIC" ? 1 : 0
  endpoint_type = var.sftp_type
  domain        = var.storage_type
  protocols     = var.protocols
  certificate   = var.certificate_arn

  endpoint_details {
    vpc_id                 = lookup(var.endpoint_details, "vpc_id", null)
    vpc_endpoint_id        = lookup(var.endpoint_details, "vpc_endpoint_id", null)
    subnet_ids             = lookup(var.endpoint_details, "subnet_ids", null)
    security_group_ids     = lookup(var.endpoint_details, "security_group_ids", aws_security_group.sftp_vpc[*].id)
    address_allocation_ids = lookup(var.endpoint_details, "address_allocation_ids", aws_eip.sftp_vpc[*].allocation_id)
  }

  identity_provider_type = var.identity_provider_type
  url                    = var.api_gw_url
  invocation_role        = var.invocation_role
  directory_id           = var.directory_id
  function               = var.function_arn

  logging_role                     = var.logging_role == null ? join(",", aws_iam_role.logging[*].arn) : var.logging_role
  force_destroy                    = var.force_destroy
  security_policy_name             = var.security_policy_name
  host_key                         = var.host_key
  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner
  structured_log_destinations      = var.cloudwatch_log_group_arns

  dynamic "protocol_details" {
    for_each = var.as2_transports == null && var.passive_ip == null && var.set_stat_option == null && var.tls_session_resumption_mode == null ? [] : [0]
    content {
      as2_transports              = var.as2_transports
      passive_ip                  = var.passive_ip
      set_stat_option             = var.set_stat_option
      tls_session_resumption_mode = var.tls_session_resumption_mode
    }
  }

  tags = merge({
    Name = local.name
  }, var.tags)
}

locals {
  server_id = var.sftp_type == "PUBLIC" ? join(",", aws_transfer_server.public[*].id) : join(",", aws_transfer_server.vpc[*].id)
  server_ep = var.sftp_type == "PUBLIC" ? join(",", aws_transfer_server.public[*].endpoint) : join(",", aws_transfer_server.vpc[*].endpoint)
}

data "aws_route53_zone" "primary" {
  count = var.hosted_zone == null ? 0 : 1
  name  = var.hosted_zone
}

resource "aws_route53_record" "sftp" {
  count   = var.hosted_zone == null ? 0 : 1
  zone_id = join(",", data.aws_route53_zone.primary[*].zone_id)
  name    = "${var.sftp_sub_domain}.${var.hosted_zone}"
  type    = "CNAME"
  ttl     = "60"
  records = [local.server_ep]
}

resource "aws_iam_role" "user" {
  for_each           = var.sftp_users
  name               = "${local.name}-sftp-user-${each.key}"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "transfer.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "user" {
  for_each = var.sftp_users
  name     = "${local.name}-sftp-user-${each.key}"
  role     = aws_iam_role.user[each.key].id

  policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowListingOfUserFolder",
      "Action": [
        "s3:ListBucket",
        "s3:GetBucketLocation"
      ],
      "Effect": "Allow",
      "Resource": [
        "arn:aws:s3:::${trimsuffix(each.value, "/")}"
      ]
    },
    {
      "Sid": "HomeDirObjectAccess",
      "Effect": "Allow",
      "Action": [
        "s3:PutObject",
        "s3:GetObject",
        "s3:DeleteObjectVersion",
        "s3:DeleteObject",
        "s3:GetObjectVersion"
      ],
      "Resource": "arn:aws:s3:::${trimsuffix(each.value, "/")}/*"
    }
  ]
}
POLICY
}

resource "aws_transfer_user" "this" {
  for_each       = var.sftp_users
  server_id      = local.server_id
  user_name      = each.key
  role           = aws_iam_role.user[each.key].arn
  home_directory = "/${each.value}"
  tags           = merge({ User = each.key }, var.tags)
}

resource "aws_transfer_ssh_key" "this" {
  for_each   = var.sftp_users_ssh_key
  server_id  = local.server_id
  user_name  = each.key
  body       = each.value
  depends_on = [aws_transfer_user.this]
}

// File: outputs.tf
output "arn" {
  value       = var.sftp_type == "PUBLIC" ? join(",", aws_transfer_server.public[*].arn) : join(",", aws_transfer_server.vpc[*].arn)
  description = "ARN of transfer server"
}

output "id" {
  value       = local.server_id
  description = "ID of transfer server"
}

output "endpoint" {
  value       = local.server_ep
  description = "Endpoint of transfer server"
}

output "domain_name" {
  value       = var.hosted_zone == null ? null : join(",", aws_route53_record.sftp[*].fqdn)
  description = "Custom DNS name mapped in Route53 for transfer server"
}

output "sftp_sg_id" {
  value       = var.sftp_type == "VPC" && lookup(var.endpoint_details, "security_group_ids", null) == null ? join(",", aws_security_group.sftp_vpc[*].id) : null
  description = "ID of security group created for SFTP server. Available only if SFTP type is VPC and security group is not provided by you"
}

output "sftp_eip" {
  value       = var.sftp_type == "VPC" && lookup(var.endpoint_details, "address_allocation_ids", null) == null ? aws_eip.sftp_vpc[*].public_ip : null
  description = "Elastic IP attached to the SFTP server. Available only if SFTP type is VPC and allocation id is not provided by you"
}

// File: requirements.tf
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.10.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.1.0"
    }
  }
}

// File: variables.tf
variable "name" {
  type        = string
  default     = null
  description = "Name of SFTP server. Ignore it to generate a random name for server"
}

variable "sftp_type" {
  type        = string
  default     = "PUBLIC"
  description = "Type of SFTP server. **Valid values:** `PUBLIC`, `VPC` or `VPC_ENDPOINT`"
}

variable "storage_type" {
  type        = string
  default     = "S3"
  description = "Where to store the files. **Valid values:** `S3` or `EFS`"
}

variable "protocols" {
  type        = list(string)
  default     = ["SFTP"]
  description = "List of file transfer protocol(s) over which your FTP client can connect to your server endpoint. **Possible Values:** FTP, FTPS and SFTP"
}

variable "certificate_arn" {
  type        = string
  default     = null
  description = "ARN of ACM certificate. Required only in case of FTPS protocol"
}

variable "endpoint_details" {
  type = object({
    vpc_id                 = optional(string)
    vpc_endpoint_id        = optional(string)
    subnet_ids             = optional(list(string))
    security_group_ids     = optional(list(string))
    address_allocation_ids = optional(list(string))
  })
  default     = {}
  description = <<-EOT
    A block required to setup SFTP server if type is set to `VPC` or `VPC_ENDPOINT`
    ```{
      vpc_id                 = (Optional) ID of VPC in which SFTP server endpoint will be hosted. Required if endpoint type is set to VPC
      vpc_endpoint_id        = (Optional) The ID of VPC endpoint to use for hosting internal SFTP server. Required if endpoint type is set to VPC_ENDPOINT
      subnet_ids             = (Optional) List of subnets ids within the VPC for hosting SFTP server endpoint. Required if endpoint type is set to VPC
      security_group_ids     = (Optional) List of security groups to attach to the SFTP endpoint. Supported only if endpoint is to type VPC. If left blank for VPC, a security group with port 22 open to the world will be created and attached
      address_allocation_ids = (Optional) List of address allocation IDs to attach an Elastic IP address to your SFTP server endpoint. Supported only if endpoint type is set to VPC. If left blank for VPC, an EIP will be automatically created per subnet and attached
    }```
  EOT
}

variable "identity_provider_type" {
  type        = string
  default     = "SERVICE_MANAGED"
  description = "Mode of authentication to use for accessing the service. **Valid Values:** `SERVICE_MANAGED`, `API_GATEWAY`, `AWS_DIRECTORY_SERVICE` or `AWS_LAMBDA`"
}

variable "api_gw_url" {
  type        = string
  default     = null
  description = "URL of the service endpoint to authenticate users when `identity_provider_type` is of type `API_GATEWAY`"
}

variable "invocation_role" {
  type        = string
  default     = null
  description = "ARN of the IAM role to authenticate the user when `identity_provider_type` is set to `API_GATEWAY`"
}

variable "directory_id" {
  type        = string
  default     = null
  description = "ID of the directory service to authenticate users when `identity_provider_type` is of type `AWS_DIRECTORY_SERVICE`"
}

variable "function_arn" {
  type        = string
  default     = null
  description = "ARN of the lambda function to authenticate users when `identity_provider_type` is of type `AWS_LAMBDA`"
}

variable "logging_role" {
  type        = string
  default     = null
  description = "ARN of an IAM role to allow to write SFTP users activity to Amazon CloudWatch logs"
}

variable "cloudwatch_log_group_arns" {
  type        = set(string)
  default     = []
  description = "Set of ARN of the CloudWatch log group to which SFTP server will write JSON logs. Required if `enable_json_logging` is set to `true`"
}

variable "force_destroy" {
  type        = bool
  default     = true
  description = "Whether to delete all the users associated with server so that server can be deleted successfully. **Note:** Supported only if `identity_provider_type` is set to `SERVICE_MANAGED`"
}

variable "security_policy_name" {
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
  description = "Specifies the name of the [security policy](https://docs.aws.amazon.com/transfer/latest/userguide/security-policies.html) to associate with the server"
}

variable "host_key" {
  type        = string
  default     = null
  description = "RSA private key that will be used to identify your server when clients connect to it over SFTP"
}

variable "pre_authentication_login_banner" {
  type        = string
  default     = null
  description = "Message to display to user when trying to connect to the server **before** authentication"
}

variable "post_authentication_login_banner" {
  type        = string
  default     = null
  description = "Message to display to user when trying to connect to the server **after** authentication"
}

variable "as2_transports" {
  type        = set(string)
  default     = null
  description = "Transport method to use for AS2 messages. **Valid values:** `HTTP`"
}

variable "passive_ip" {
  type        = string
  default     = null
  description = "Use passive IP (PASV) capability to attach the IP address of the firewall or the load balancer to your FTPS/FTP server"
}

variable "set_stat_option" {
  type        = string
  default     = null
  description = "Whether the server should ignore SETSTAT command. **Valid values:** `DEFAULT`, `ENABLE_NO_OP`"
}

variable "tls_session_resumption_mode" {
  type        = string
  default     = null
  description = "TLS session resumption mode provides a mechanism to resume recently negotiated encrypted TLS sessions between the client and the FTPS server. Using one of the TLS session resumption modes, you can customize how you want to your FTPS server to process TLS session resumption requests"
}

variable "hosted_zone" {
  type        = string
  default     = null
  description = "Hosted zone name to create DNS entry for SFTP server"
