// File: main.tf
# ---------------------------------------------------------------------------------------------------------------------
# CREATE IAM ROLES AND POLICIES TO SUPPORT EMR AUTOSCALING AND CONNECTIONS TO AWS SERVICES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "assume_role_emr" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["elasticmapreduce.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "assume_role_ec2" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "application_autoscaling" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["application-autoscaling.amazonaws.com", "elasticmapreduce.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "emr" {
  name               = "${var.name_prefix}-emr-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role_emr.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "emr" {
  role       = aws_iam_role.emr.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEMRServicePolicy_v2"
}

resource "aws_iam_role" "ec2" {
  name               = "${var.name_prefix}-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role_ec2.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ec2" {
  role = aws_iam_role.ec2.name
  # NOTE: Deprecated, but with no replacement policy; we'd need to develop our own
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "cloudwatch" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ssm" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = aws_iam_role.ec2.name
  role = aws_iam_role.ec2.name
}

resource "aws_iam_role" "ec2_autoscaling" {
  name               = "${var.name_prefix}-ec2-autoscaling-role"
  assume_role_policy = data.aws_iam_policy_document.application_autoscaling.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ec2_autoscaling" {
  role       = aws_iam_role.ec2_autoscaling.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceforAutoScalingRole"
}

// File: outputs.tf
output "emr_role_arn" {
  description = "The ARN of the EMR role"
  value       = aws_iam_role.emr.arn
}

output "emr_role_name" {
  description = "The name of the EMR role"
  value       = aws_iam_role.emr.name
}

output "emr_role_unique_id" {
  description = "The stable and unique string identifying the EMR role"
  value       = aws_iam_role.emr.unique_id
}

output "ec2_role_arn" {
  description = "The ARN of the EC2 role"
  value       = aws_iam_role.ec2.arn
}

output "ec2_role_name" {
  description = "The name of the EC2 role"
  value       = aws_iam_role.ec2.name
}

output "ec2_role_unique_id" {
  description = "The stable and unique string identifying the EC2 role"
  value       = aws_iam_role.emr.unique_id
}

output "ec2_autoscaling_role_arn" {
  description = "The ARN of the EC2 autoscaling role"
  value       = aws_iam_role.ec2_autoscaling.arn
}

output "ec2_autoscaling_role_name" {
