// File: main.tf
resource "aws_ecr_repository" "this" {
  name                 = var.name
  image_tag_mutability = var.mutability

  encryption_configuration {
    encryption_type = var.kms_encryption == true ? "KMS" : "AES256"
    kms_key         = var.kms_encryption == true ? aws_kms_key.this[0].arn : null
  }
  force_delete = var.force_delete
  tags         = var.tags
}

data "aws_iam_policy_document" "this_policy" {
  count = var.allowed_principals != null ? 1 : 0
  statement {
    sid    = "AllowPull"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.allowed_principals
    }

    actions = [
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability",
      "ecr:DescribeRepositories",
      "ecr:GetRepositoryPolicy",
      "ecr:ListImages",
    ]
  }
}

resource "aws_ecr_repository_policy" "this" {
  count      = var.allowed_principals != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.this_policy[0].json
}

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = jsonencode(var.lifecycle_policy)
}

resource "aws_kms_key" "this" {
  count               = var.kms_encryption == true ? 1 : 0
  enable_key_rotation = true
  tags                = var.tags
}

resource "aws_kms_alias" "this" {
  count         = var.kms_encryption == true ? 1 : 0
  name          = "alias/ecr/repository/${var.name}"
  target_key_id = aws_kms_key.this[0].key_id
}

// File: outputs.tf
output "arn" {
  value       = aws_ecr_repository.this.arn
  description = "Repository ARN"
}

output "repository_url" {
  value       = aws_ecr_repository.this.repository_url
  description = "Repository URL"
}

output "kms_key_id" {
  value       = aws_kms_key.this[*].key_id
  description = "KMS Key ID"
}

output "kms_key_arn" {
  value       = aws_kms_key.this[*].arn
  description = "KMS key ARN"
}

// File: provider.tf
terraform {
  required_version = ">= 1.4.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

// File: variables.tf
variable "name" {
  default     = "my-ecr-repo"
  type        = string
  description = "ECR Repo name"
}
variable "mutability" {
  default     = "MUTABLE"
  description = "MUTABLE or IMMUTABLE"
  type        = string
}
variable "kms_encryption" {
  default     = false
  description = "Enables KMS encryption for the repo. Default is AES256"
  type        = bool
}
variable "force_delete" {
  default     = false
  description = "When enabled, you can delete the repository when there are images inside."
  type        = bool
}
variable "tags" {
  default     = null
  description = "tags that are added to the repository (and KMS keys)"
  type        = map(any)
}

variable "allowed_principals" {
  default     = null
  description = "List of AWS account IDs or ARNs that are allowed to pull images"
  type        = list(any)
}

variable "lifecycle_policy" {
  default     = null
  description = "Lifecycle policy IAM document"
  type        = string
}

// File: main.tf
##################################################################################
# PROVIDERS
##################################################################################

provider "aws" {
  access_key = "ACCESS_KEY"
  secret_key = "SECRET_KEY"
  region     = "us-east-1"
}

##################################################################################
# DATA
##################################################################################

data "aws_ssm_parameter" "ami" {
  name = "/aws/service/ami-amazon-linux-latest/amzn2-ami-hvm-x86_64-gp2"
}

##################################################################################
# RESOURCES
##################################################################################

# NETWORKING #
resource "aws_vpc" "vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = "true"

}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id

}

resource "aws_subnet" "subnet1" {
  cidr_block              = "10.0.0.0/24"
  vpc_id                  = aws_vpc.vpc.id
  map_public_ip_on_launch = "true"
}

# ROUTING #
resource "aws_route_table" "rtb" {
  vpc_id = aws_vpc.vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

resource "aws_route_table_association" "rta-subnet1" {
  subnet_id      = aws_subnet.subnet1.id
  route_table_id = aws_route_table.rtb.id
}

# SECURITY GROUPS #
# Nginx security group 
resource "aws_security_group" "nginx-sg" {
  name   = "nginx_sg"
  vpc_id = aws_vpc.vpc.id

  # HTTP access from anywhere
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # outbound internet access
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# INSTANCES #
resource "aws_instance" "nginx1" {
  ami                    = nonsensitive(data.aws_ssm_parameter.ami.value)
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.subnet1.id
  vpc_security_group_ids = [aws_security_group.nginx-sg.id]

  user_data = <<EOF
#! /bin/bash
sudo amazon-linux-extras install -y nginx1
sudo service nginx start
sudo rm /usr/share/nginx/html/index.html
echo '<html><head><title>Taco Team Server</title></head><body style=\"background-color:#1F778D\"><p style=\"text-align: center;\"><span style=\"color:#FFFFFF;\"><span style=\"font-size:28px;\">You did it! Have a &#127790;</span></span></p></body></html>' | sudo tee /usr/share/nginx/html/index.html
EOF

}

// File: main.tf
resource "random_pet" "lambda_bucket_name" {
  prefix = "hello-world-lambda"
  length = 2
}

resource "aws_s3_bucket" "lambda_bucket" {
  bucket = random_pet.lambda_bucket_name.id
}

resource "aws_s3_bucket_ownership_controls" "bucket_controls" {
  bucket = aws_s3_bucket.lambda_bucket.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "bucket_acl" {
  depends_on = [aws_s3_bucket_ownership_controls.bucket_controls]

  bucket = aws_s3_bucket.lambda_bucket.id
  acl    = "private"
}

// File: outputs.tf
output "bucket_id" {
  description = "The ID of the S3 bucket to be used by a downstream component in this stack."

  value = aws_s3_bucket.lambda_bucket.id
}

// File: outputs.tf
output "id" {
  value       = aws_vpc.default.id
  description = "VPC id"
}

output "public_subnet_ids" {
  value       = aws_subnet.public.*.id
  description = "List of public subnet IDs"
}

output "cidr_block" {
  value       = var.cidr_block
  description = "The CIDR block associated with the VPC"
}

// File: variables.tf
variable "project" {
  default     = "demo"
  type        = string
  description = "Name of project this VPC is meant to house"
}

variable "environment" {
  default     = "poc"
  type        = string
  description = "Name of environment this VPC is targeting"
}

variable "name" {
  default     = "demo-dataflow"
  type        = string
  description = "Name of the VPC"
}

variable "region" {
  default     = "us-west-2"
  type        = string
  description = "Region of the VPC"
}

variable "availability_zones" {
  default     = ["us-west-2a", "us-west-2b"]
  type        = list
  description = "List of availability zones"
}

variable "key_name" {
  default     = "kplinuxdemo"
  type        = string
  description = "EC2 Key pair name for the bastion"
}

variable "cidr_block" {
  default     = "10.0.0.0/16"
  type        = string
  description = "CIDR block for the VPC"
}

variable "public_subnet_cidr_blocks" {
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
  type        = list
  description = "List of public subnet CIDR blocks"
}

variable "private_subnet_cidr_blocks" {
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
  type        = list
  description = "List of private subnet CIDR blocks"
}

variable "aws_internet_gateway" {
  default     = "igwdemo"
  type        = string
  description = "Region of the VPC"
}

variable "bastion_ami" {
  default     = " ami-0d6621c01e8c2de2c"
  type        = string
  description = "Bastion Amazon Machine Image (AMI) ID"
}

variable "bastion_ebs_optimized" {
  default     = false
  type        = bool
  description = "If true, the bastion instance will be EBS-optimized"
}

variable "bastion_instance_type" {
  default     = "t3.nano"
  type        = string
  description = "Instance type for bastion instance"
}

variable "tags" {
  default     = {}
  type        = map(string)
  description = "Extra tags to attach to the VPC resources"
}

// File: vpc.tf
#
# VPC resources
#

provider "aws" {
  region = var.region
}

resource "aws_vpc" "default" {
  cidr_block           = var.cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    {
      Name        = var.name,
      Project     = var.project,
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_internet_gateway" "default" {
  vpc_id = aws_vpc.default.id

  tags = merge(
    {
      Name        = "demogwInternet",
      Project     = var.project,
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidr_blocks)

  vpc_id                  = aws_vpc.default.id
  cidr_block              = var.public_subnet_cidr_blocks[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = true

  tags = merge(
    {
      Name        = "demoPublicSubnet",
      Project     = var.project,
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.default.id

  tags = merge(
    {
      Name        = "demoPublicRouteTable",
      Project     = var.project,
      Environment = var.environment
    },
    var.tags
  )
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.default.id
}

// File: main.tf
# Copyright IBM Corp. 2014, 2026
# SPDX-License-Identifier: MPL-2.0

terraform {
  required_version = ">= 0.12"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "AWSElasticDisasterRecoveryAgentRole" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity"
        ]
        Condition = {
          StringLike = {
            "sts:SourceIdentity" = "s-*",
            "aws:SourceAccount"  = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "AWSElasticDisasterRecoveryFailbackRole" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity"
        ]
        Condition = {
          StringLike = {
            "sts:SourceIdentity" = "i-*",
            "aws:SourceAccount"  = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "AWSElasticDisasterRecoveryConversionServerRole" {
  name = "AWSElasticDisasterRecoveryConversionServerRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
