// File: ses_active_receipt_rule_set.tf
#---------------------------------------------------
# AWS ses active receipt rule set
#---------------------------------------------------
resource "aws_ses_active_receipt_rule_set" "ses_active_receipt_rule_set" {
  count = var.enable_ses_active_receipt_rule_set ? 1 : 0

  rule_set_name = var.ses_active_receipt_rule_set_rule_set_name != "" ? var.ses_active_receipt_rule_set_rule_set_name : "${lower(var.name)}-ses-active-receipt-rule-set-${lower(var.environment)}"

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: ses_configuration_set.tf
#---------------------------------------------------
# AWS ses configuration set
#---------------------------------------------------
resource "aws_ses_configuration_set" "ses_configuration_set" {
  count = var.enable_ses_configuration_set ? 1 : 0

  name = var.ses_configuration_set_name != "" ? var.ses_configuration_set_name : "${lower(var.name)}-ses-configuration-set-${lower(var.environment)}"

  reputation_metrics_enabled = var.ses_configuration_set_reputation_metrics_enabled
  sending_enabled            = var.ses_configuration_set_sending_enabled

  dynamic "delivery_options" {
    iterator = delivery_options
    for_each = length(keys(var.ses_configuration_set_delivery_options)) > 0 ? [var.ses_configuration_set_delivery_options] : []

    content {
      tls_policy = lookup(delivery_options.value, "tls_policy", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: ses_domain_dkim.tf
#---------------------------------------------------
# AWS ses domain dkim
#---------------------------------------------------
resource "aws_ses_domain_dkim" "ses_domain_dkim" {
  count = var.enable_ses_domain_dkim ? 1 : 0

  domain = var.ses_domain_dkim_domain != "" ? var.ses_domain_dkim_domain : (var.enable_ses_domain_identity ? aws_ses_domain_identity.ses_domain_identity[count.index].domain : null)

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: ses_domain_identity.tf
#---------------------------------------------------
# AWS ses domain identity
#---------------------------------------------------
resource "aws_ses_domain_identity" "ses_domain_identity" {
  count = var.enable_ses_domain_identity ? length(var.ses_domain_identity_domains) : 0

  domain = var.ses_domain_identity_domains[count.index]

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: ses_domain_identity_verification.tf
#---------------------------------------------------
