// File: versions.tf
terraform {
  required_version = ">= 0.12.6"

  required_providers {
    aws = ">= 2.23"
  }
}

// File: data.tf
data "aws_caller_identity" "current" {}
data "aws_iam_policy_document" "s3_bucket_force_ssl" {
  statement {
    sid     = "S3TFBucketOnlyAllowTLS"
    actions = ["S3:*"]
    effect  = "Deny"
    resources = [
      aws_s3_bucket.state_bucket.arn,
      "${aws_s3_bucket.state_bucket.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
    principals {
      type        = "*"
      identifiers = ["*"]
    }
  }
}

// File: dynamodb.tf
resource "aws_dynamodb_table" "state_locking" {
  name         = var.dynamodb_table_name
  billing_mode = var.dynamodb_billing_mode
  hash_key     = "LockID" # See https://www.terraform.io/docs/backends/types/s3.html#dynamodb_table

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.bucket_encryption_key.arn
  }

  tags = var.tagging
}

// File: kms.tf
resource "aws_kms_key" "bucket_encryption_key" {
  description = "TF backend bucket encryption key"

  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = var.kms_key_deletion_window
  enable_key_rotation     = var.kms_key_rotation_enabled

  policy = jsonencode({
    Version = "2012-10-17"
    ID      = "Enable IAM permissions from this account"
    Statement = [
      {
        SID    = "Allow root all actions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        },
        Action   = "kms:*"
        Resource = "*"
      }
    ]
    }
  )

  tags = var.tagging
}

resource "aws_kms_alias" "bucket_encryption_key_alias" {
  name          = "alias/${local.bucket_name}-key"
  target_key_id = aws_kms_key.bucket_encryption_key.key_id
}

// File: locals.tf
locals {
  bucket_name = "${random_pet.rando.id}-${var.bucket_name_suffix}"
}

// File: main.tf
# Random name generation
resource "random_pet" "rando" {}

// File: outputs.tf
output "bucket_name" {
  description = "The name of the bucket"
  value       = local.bucket_name
}

// File: s3.tf
# State Bucket

resource "aws_s3_bucket" "state_bucket" {
  #checkov:skip=CKV2_AWS_61:Deprecated, Handled in aws_s3_bucket_lifecycle_configuration
  #checkov:skip=CKV2_AWS_62:Handled in TF/Pipeline
  #checkov:skip=CKV_AWS_144:Don't see the point for terraform. if you want it, make more buckets in EU or something.
  bucket = var.custom_bucket_name != null ? var.custom_bucket_name : local.bucket_name

  tags = var.tagging
}

resource "aws_s3_bucket_policy" "s3_bucket_force_ssl" {
  bucket = aws_s3_bucket.state_bucket.id
  policy = data.aws_iam_policy_document.s3_bucket_force_ssl.json
}

resource "aws_s3_bucket_versioning" "state_bucket_versioning" {
  bucket = aws_s3_bucket.state_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state_bucket_lifecycle" {
  bucket = aws_s3_bucket.state_bucket.id
  rule {
    id     = "abort-failed-uploads"
    status = "Enabled"

    abort_incomplete_multipart_upload {
      days_after_initiation = 1
    }
  }
  rule {
    id     = "auto-archive"
    status = "Enabled"

    dynamic "noncurrent_version_transition" {
      for_each = var.noncurrent_version_transitions

      content {
        noncurrent_days = noncurrent_version_transition.value.days
        storage_class   = noncurrent_version_transition.value.storage_class
      }
    }

    dynamic "noncurrent_version_expiration" {
      for_each = var.noncurrent_version_expiration != null ? [var.noncurrent_version_expiration] : []

      content {
        noncurrent_days = noncurrent_version_expiration.value.days
      }
    }
  }
}

resource "aws_s3_bucket_logging" "state_bucket_logging" {
  bucket = aws_s3_bucket.state_bucket.id

  target_bucket = aws_s3_bucket.state_logging_bucket.id
  target_prefix = "tfstate/"
}

resource "aws_s3_bucket_ownership_controls" "state_bucket_ownership" {
  #checkov:skip=CKV2_AWS_65:This is unnecessary with IAM, no public, etc. what about several teams using one bucket in an Org?
  bucket = aws_s3_bucket.state_bucket.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "state_bucket_public_access_blocking" {
  bucket = aws_s3_bucket.state_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_bucket_encryption" {
  bucket = aws_s3_bucket.state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.bucket_encryption_key.key_id
      sse_algorithm     = "aws:kms"
    }
  }
}


# Logging Bucket

resource "aws_s3_bucket" "state_logging_bucket" {
  #checkov:skip=CKV_AWS_21:Logging Bucket versioning is unnecessary for logging bucket
  #checkov:skip=CKV2_AWS_61:Deprecated, Handled in aws_s3_bucket_lifecycle_configuration
  #checkov:skip=CKV2_AWS_62:Handled by pipeline/terraform
  #checkov:skip=CKV_AWS_144:No point in terraform.
  bucket = "${aws_s3_bucket.state_bucket.id}-logging"

  tags = var.tagging
}

resource "aws_s3_bucket_ownership_controls" "state_logging_bucket_ownership" {
  #checkov:skip=CKV2_AWS_65:This is to handle multi-account Orgs.
  bucket = aws_s3_bucket.state_logging_bucket.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "state_logging_bucket_public_access_blocking" {
  bucket = aws_s3_bucket.state_logging_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_logging_bucket_encryption" {
  bucket = aws_s3_bucket.state_logging_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.bucket_encryption_key.key_id
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state_logging_bucket_lifecycle" {
  #checkov:skip=CKV_AWS_300:If AWS is failing their own uploads, there are other issues.
  bucket = aws_s3_bucket.state_logging_bucket.id

  rule {
    id     = "auto-archive"
    status = "Enabled"

    dynamic "noncurrent_version_transition" {
      for_each = var.noncurrent_log_version_transitions

      content {
        noncurrent_days = noncurrent_version_transition.value.days
        storage_class   = noncurrent_version_transition.value.storage_class
      }
    }

    dynamic "noncurrent_version_expiration" {
      for_each = var.noncurrent_log_version_expiration != null ? [var.noncurrent_log_version_expiration] : []

      content {
        noncurrent_days = noncurrent_version_expiration.value.days
      }
    }
  }
}

// File: terraform.tf
terraform {
  required_version = ">=1.9.0, <2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.60.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "3.6.2"
    }
  }
}

provider "aws" {
  region  = var.region
  profile = var.profile

  default_tags {
    tags = {
      Terraform = "true"
    }
  }
}

// File: variables.tf
variable "region" {
  description = "What AWS region do you want your backend to live in?"

  type    = string
  default = "us-west-2"
}

variable "profile" {
  description = "The aws STS/SSO profile to use"

  type    = string
  default = "default"
}

variable "tagging" {
  description = "an optional map to hold tags see README.md > Tag Example"

  type     = map(string)
  default  = {}
  nullable = true
}

#KMS Variables

variable "kms_key_deletion_window" {
  description = "Number of days to retain deleted KMS keys for backup purposes."

  type    = number
  default = 10
}

variable "kms_key_rotation_enabled" {
  description = "Whether or not to enable KMS rotation. Almost always a good idea."

  type    = bool
  default = true
}

# S3 Bucket Variables

variable "custom_bucket_name" {
  description = "This is if you want to create a completely custom name. Remember, S3 bucket names _must_ be globally unique. Good luck!"
  type        = string
  default     = null
}

variable "bucket_name_suffix" {
  description = <<-EOL
    This module concatenates a prefix string using
    [`random_pet`](https://registry.terraform.io/providers/hashicorp/random/latest/docs/resources/pet)
    to help ensure [globally-unique names](https://docs.aws.amazon.com/AmazonS3/latest/userguide/UsingBucket.html)
  EOL

  type    = string
  default = "tf-backend"
}

variable "noncurrent_version_transitions" {
  description = "Specifies when noncurrent object versions transitions. See the aws_s3_bucket document for detail."

  type = list(object({
    days          = number
    storage_class = string
  }))

  default = [
    {
      days          = 30
      storage_class = "GLACIER"
    }
  ]
}

variable "noncurrent_version_expiration" {
  description = "Specifies when noncurrent object versions expire. See the aws_s3_bucket document for detail."

  type = object({
    days = number
  })

  default = null
}

variable "noncurrent_log_version_transitions" {
  description = "Specifies when noncurrent object versions transitions. See the aws_s3_bucket document for detail."

  type = list(object({
    days          = number
    storage_class = string
  }))

  default = [
    {
      days          = 90
      storage_class = "GLACIER"
    }
  ]
}

variable "noncurrent_log_version_expiration" {
  description = "Specifies when noncurrent object versions expire. See the aws_s3_bucket document for detail."

  type = object({
    days = number
  })

  default = null
}

# DynamoDB Variables

variable "dynamodb_table_name" {
  description = "Name for the locking table"

  type    = string
  default = "tf_state_lock"
}

variable "dynamodb_billing_mode" {
  description = <<-EOL
    The billing mode for the DynamoDB locking table. For low-volume (<50 runs/day), PAY_PER_REQUEST is considerably
    less exensive. Switch to PROVISIONED if you need autoscaling (niche).
  EOL

  type    = string
  default = "PAY_PER_REQUEST"
}

// File: cloud_credential_role.tf
resource "aws_iam_role" "cloud-credential_role" {
  count = length(var.clusters)
  name = "${var.clusters[count.index].operator_role_prefix}-openshift-cloud-credential-operator-cloud-c"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Condition = {
            StringEquals = {
                "rh-oidc.s3.us-east-1.amazonaws.com/${var.clusters[count.index].id}:sub" = ["system:serviceaccount:openshift-cloud-credential-operator:cloud-credential-operator"]
            }
        }
        Principal = {
          Federated = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/rh-oidc.s3.us-east-1.amazonaws.com/${var.clusters[count.index].id}"
        }
      },
    ]
  })

  tags = {
    rosa_cluster_id = var.clusters[count.index].id
    rosa_role_prefix = "ManagedOpenShift"
    operator_namespace = "openshift-cloud-credential-operator"
    operator_name = "cloud-credential-operator-iam-ro-creds"
  }
}

resource "aws_iam_role_policy_attachment" "cloud-credential_role_policy_attachment" {
  count = length(var.clusters)
  role = aws_iam_role.cloud-credential_role[count.index].name
  policy_arn = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/ManagedOpenShift-openshift-cloud-credential-operator-cloud-crede"
}

// File: cloud_identity_provider.tf
resource "aws_iam_openid_connect_provider" "oidc_provider" {
  count = length(var.clusters)
  url = "${var.rh_oidc_provider_url}/${var.clusters[count.index].id}"

  client_id_list = [
    "openshift",
    "sts.amazonaws.com"
  ]

  tags = {
    rosa_cluster_id = var.clusters[count.index].id
  }

  thumbprint_list = [var.rh_oidc_provider_thumbprint]
}

