// File: config_aggregate_authorization.tf
#---------------------------------------------------
# AWS config aggregate authorization
#---------------------------------------------------
resource "aws_config_aggregate_authorization" "config_aggregate_authorization" {
  count = var.enable_config_aggregate_authorization ? 1 : 0

  account_id = var.config_aggregate_authorization_account_id
  region     = var.region

  tags = merge(
    {
      Name = var.config_aggregate_authorization_name != "" ? lower(var.config_aggregate_authorization_name) : "${lower(var.name)}-config-aggregate-auth-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: config_config_rule.tf
#---------------------------------------------------
# AWS config config rule
#---------------------------------------------------
resource "aws_config_config_rule" "config_config_rule" {
  count = var.enable_config_config_rule ? 1 : 0

  name                        = var.config_config_rule_name != "" ? lower(var.config_config_rule_name) : "${lower(var.name)}-config-rule-${lower(var.environment)}"
  description                 = var.config_config_rule_description
  input_parameters            = var.config_config_rule_input_parameters
  maximum_execution_frequency = var.config_config_rule_maximum_execution_frequency

  dynamic "source" {
    iterator = source
    for_each = var.config_config_rule_source

    content {
      owner             = lookup(source.value, "owner", "AWS")
      source_identifier = lookup(source.value, "source_identifier", "S3_BUCKET_VERSIONING_ENABLED")
    }
  }

  dynamic "scope" {
    iterator = scope
    for_each = var.config_config_rule_scope

    content {
      compliance_resource_id    = lookup(scope.value, "compliance_resource_id", null)
      compliance_resource_types = lookup(scope.value, "compliance_resource_types", null)
      tag_key                   = lookup(scope.value, "tag_key", null)
      tag_value                 = lookup(scope.value, "tag_value", null)
    }
  }

  tags = merge(
    {
      Name = var.config_config_rule_name != "" ? lower(var.config_config_rule_name) : "${lower(var.name)}-config-rule-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: config_configuration_aggregator.tf
#---------------------------------------------------
# AWS config configuration aggregator
#---------------------------------------------------
resource "aws_config_configuration_aggregator" "config_configuration_aggregator" {
  count = var.enable_config_configuration_aggregator ? 1 : 0

  name = var.config_configuration_aggregator_name != "" ? lower(var.config_configuration_aggregator_name) : "${lower(var.name)}-config-aggregator-${lower(var.environment)}"

  dynamic "account_aggregation_source" {
    iterator = account_aggregation_source
    for_each = var.config_configuration_aggregator_account_aggregation_source

    content {
      account_ids = lookup(account_aggregation_source.value, "account_ids", null)
      regions     = lookup(account_aggregation_source.value, "regions", null)
      all_regions = lookup(account_aggregation_source.value, "all_regions", null)
    }
  }

  dynamic "organization_aggregation_source" {
    iterator = organization_aggregation_source
    for_each = var.config_configuration_aggregator_organization_aggregation_source

    content {
      all_regions = lookup(organization_aggregation_source.value, "all_regions", null)
      regions     = lookup(organization_aggregation_source.value, "regions", null)
      role_arn    = lookup(organization_aggregation_source.value, "role_arn", null)
    }
  }

  tags = merge(
    {
      Name = var.config_configuration_aggregator_name != "" ? lower(var.config_configuration_aggregator_name) : "${lower(var.name)}-config-aggregator-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

