// File: example_1.tf
data "aws_iam_policy_document" "example_1_trust_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::111222333444:root"] # SNYK-CC-TF-118 violation due to "arn:aws:iam::111222333444:root"
    }
  }
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = ["arn:aws:iam::111222333444:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/FOO"]
    }
    condition {
      test     = "StringLike"
      variable = "oidc.eks.us-west-2.amazonaws.com/id/FOO:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringLike"
      variable = "oidc.eks.us-west-2.amazonaws.com/id/FOO:sub"
      values   = ["system:serviceaccount:*:*"] # This allows any Kubernetes Service Account in any Kubernetes Namespace in EKS Cluster ID `FOO` to assume `example_role`
    }
  }
}

resource "aws_iam_role" "example_1_role" {
  assume_role_policy  = data.aws_iam_policy_document.example_1_trust_policy.json
  managed_policy_arns = []
}

// File: example_2.tf
resource "aws_iam_role" "example_2_role" {
  assume_role_policy = jsonencode(
    {
      Statement = [
        {
          Effect = "Allow"
          Action = "sts:AssumeRole"
          Principal = {
            AWS = "arn:aws:iam::111222333444:root" # SNYK-CC-TF-118 violation due to "arn:aws:iam::111222333444:root"
          }
        },
        {
          Effect = "Allow"
          Action = "sts:AssumeRoleWithWebIdentity"
          Principal = {
            Federated = "arn:aws:iam::111222333444:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/FOO"
          }
          Condition = {
            StringLike = {
              "oidc.eks.us-west-2.amazonaws.com/id/FOO:aud" = "sts.amazonaws.com"
              "oidc.eks.us-west-2.amazonaws.com/id/FOO:sub" = "system:serviceaccount:*:*" # This allows any Kubernetes Service Account in any Kubernetes Namespace in EKS Cluster ID `FOO` to assume `example_role`
            }
          }

        }
      ]
      Version = "2012-10-17"
    }
  )
  managed_policy_arns = []
}

