// File: athena_data_catalog.tf
#---------------------------------------------------
# AWS athena data catalog
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/athena_data_catalog

// File: athena_database.tf
#---------------------------------------------------
# AWS athena database
#---------------------------------------------------
resource "aws_athena_database" "athena_database" {
  count = var.enable_athena_database ? 1 : 0

  name   = var.athena_database_name != "" ? var.athena_database_name : "${lower(var.name)}-athena-db-${lower(var.environment)}"
  bucket = var.athena_database_bucket

  force_destroy = var.athena_database_force_destroy

  dynamic "encryption_configuration" {
    iterator = encryption_configuration
    for_each = var.athena_database_encryption_configuration

    content {
      encryption_option = lookup(encryption_configuration.value, "encryption_option", null)

      kms_key = lookup(encryption_configuration.value, "kms_key", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: athena_named_query.tf
#---------------------------------------------------
# AWS athena named query
#---------------------------------------------------
resource "aws_athena_named_query" "athena_named_query" {
  count = var.enable_athena_named_query ? 1 : 0

  name     = var.athena_named_query_name != "" ? lower(var.athena_named_query_name) : "${lower(var.name)}-athena-query-${lower(var.environment)}"
  database = var.athena_named_query_database != "" && !var.enable_athena_database ? var.athena_named_query_database : element(concat(aws_athena_database.athena_database.*.name, [""]), 0)
  query    = var.athena_named_query_query

  description = var.athena_named_query_description != "" ? var.athena_named_query_description : null
  workgroup   = var.athena_named_query_workgroup != "" && !var.enable_athena_workgroup ? var.athena_named_query_workgroup : element(concat(aws_athena_workgroup.athena_workgroup.*.id, [""]), 0)

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_athena_workgroup.athena_workgroup,
    aws_athena_database.athena_database
  ]
}

// File: athena_workgroup.tf
#---------------------------------------------------
# AWS athena workgroup
#---------------------------------------------------
resource "aws_athena_workgroup" "athena_workgroup" {
  count = var.enable_athena_workgroup ? 1 : 0

  name = var.athena_workgroup_name != "" ? lower(var.athena_workgroup_name) : "${lower(var.name)}-athena-workgroup-${lower(var.environment)}"

  description   = var.athena_workgroup_description
  state         = upper(var.athena_workgroup_state)
  force_destroy = var.athena_workgroup_force_destroy

  dynamic "configuration" {
    iterator = configuration
    for_each = var.athena_workgroup_configuration

    content {
      bytes_scanned_cutoff_per_query     = lookup(configuration.value, "bytes_scanned_cutoff_per_query", null)
      enforce_workgroup_configuration    = lookup(configuration.value, "enforce_workgroup_configuration", null)
      publish_cloudwatch_metrics_enabled = lookup(configuration.value, "publish_cloudwatch_metrics_enabled", null)

      dynamic "result_configuration" {
        iterator = result_configuration
        for_each = length(keys(lookup(configuration.value, "result_configuration", {}))) > 0 ? [lookup(configuration.value, "result_configuration", {})] : []

        content {
          output_location = lookup(result_configuration.value, "output_location", null)

          dynamic "encryption_configuration" {
            iterator = encryption_configuration
            for_each = length(keys(lookup(result_configuration.value, "encryption_configuration", {}))) > 0 ? [lookup(result_configuration.value, "encryption_configuration", {})] : []

            content {
              encryption_option = lookup(encryption_configuration.value, "encryption_option", null)
              kms_key_arn       = lookup(encryption_configuration.value, "kms_key_arn", null)
            }
          }
        }
      }
    }
  }

  tags = merge(
    {
      Name = var.athena_workgroup_name != "" ? lower(var.athena_workgroup_name) : "${lower(var.name)}-athena-workgroup-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: outputs.tf
#---------------------------------------------------
# ASW athena database
#---------------------------------------------------
output "athena_database_id" {
  description = "The database name"
  value       = element(concat(aws_athena_database.athena_database.*.id, [""]), 0)
}

#---------------------------------------------------
# ASW athena named query
#---------------------------------------------------
output "athena_named_query_id" {
  description = "The unique ID of the query."
  value       = element(concat(aws_athena_named_query.athena_named_query.*.id, [""]), 0)
}

#---------------------------------------------------
# AWS athena workgroup
#---------------------------------------------------
output "athena_workgroup_id" {
  description = "The workgroup name"
  value       = element(concat(aws_athena_workgroup.athena_workgroup.*.id, [""]), 0)
}

output "athena_workgroup_arn" {
  description = "Amazon Resource Name (ARN) of the workgroup"
  value       = element(concat(aws_athena_workgroup.athena_workgroup.*.arn, [""]), 0)
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks. Each element should have keys named key, value, and propagate_at_launch."
  type        = map(string)
  default     = {}
}

#---------------------------------------------------
# ASW athena database
#---------------------------------------------------
variable "enable_athena_database" {
  description = "Enable athena DB usage"
  default     = false
}

variable "athena_database_name" {
  description = "Name of the database to create."
  default     = ""
}

variable "athena_database_bucket" {
  description = "(Required) Name of s3 bucket to save the results of the query execution."
  default     = ""
}

variable "athena_database_force_destroy" {
  description = "(Optional, Default: false) A boolean that indicates all tables should be deleted from the database so that the database can be destroyed without error. The tables are not recoverable."
  default     = false
}

variable "athena_database_encryption_configuration" {
  description = "(Optional) The encryption key block AWS Athena uses to decrypt the data in S3, such as an AWS Key Management Service (AWS KMS) key. An encryption_configuration block is documented below."
  default     = []
}

#---------------------------------------------------
# ASW athena named query
#---------------------------------------------------
variable "enable_athena_named_query" {
  description = "Enable athena named query usage"
  default     = false
}

variable "athena_named_query_name" {
  description = "The plain language name for the query. Maximum length of 128."
  default     = ""
}

variable "athena_named_query_workgroup" {
  description = "(Optional) The workgroup to which the query belongs. Defaults to primary"
  default     = "primary"
}

variable "athena_named_query_database" {
  description = "The database to which the query belongs."
  default     = ""
}

variable "athena_named_query_description" {
  description = "(Optional) A brief explanation of the query. Maximum length of 1024."
  default     = ""
}

variable "athena_named_query_query" {
  description = "(Required) The text of the query itself. In other words, all query statements. Maximum length of 262144."
  default     = ""
}

#---------------------------------------------------
# AWS athena workgroup
#---------------------------------------------------
variable "enable_athena_workgroup" {
  description = "Enable athena workgroup usage"
  default     = false
}

variable "athena_workgroup_name" {
  description = "Name of the workgroup."
  default     = ""
}

variable "athena_workgroup_description" {
  description = "(Optional) Description of the workgroup."
  default     = null
}

variable "athena_workgroup_state" {
  description = "(Optional) State of the workgroup. Valid values are DISABLED or ENABLED. Defaults to ENABLED."
  default     = null
}

variable "athena_workgroup_force_destroy" {
  description = "(Optional) The option to delete the workgroup and its contents even if the workgroup contains any named queries."
  default     = null
}

variable "athena_workgroup_configuration" {
  description = "(Optional) Configuration block with various settings for the workgroup."
  default     = []
}

// File: main.tf
resource "aws_vpc" "this" {
  cidr_block = var.vpc_cidr_block

  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-vpc"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id            = aws_vpc.this.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-private-subnet-${var.availability_zones[count.index]}"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnets)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-public-subnet-${var.availability_zones[count.index]}"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-igw"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = var.all_ips
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name        = "${var.environment}-${var.cluster_name}-public-rt"
    ManagedBy   = "Terraform"
    environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnets)

  route_table_id = aws_route_table.public.id
  subnet_id      = aws_subnet.public[count.index].id
}

// File: outputs.tf
output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.this.id
}

output "private_subnet_ids" {
  description = "ID of the private subnets of this VPC"
  value       = aws_subnet.private[*].id
}

output "public_subnet_ids" {
  description = "ID of the public subnets of this VPC"
  value       = aws_subnet.public[*].id
}

// File: variables.tf
variable "cluster_name" {
  description = "Cluster name to identify all resources"
  type        = string
  default     = "Fast-App"
}

variable "aws_region" {
  description = "The AWS region things are created in"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "the environment we will be deploying for"
  type        = string
  default     = "dev"
}
variable "vpc_cidr_block" {
  description = "CIDR (Classless Inter-Domain Routing)"
  type        = string
  default     = "10.0.0.0/16"
}

variable "all_ips" {
  description = "CIDR (Classless Inter-Domain Routing) for all IP"
  type        = string
  default     = "0.0.0.0/0"
}

variable "availability_zones" {
  description = "Subnet Availability Zones"
  type = list(string)
  default = ["us-east-1a", "us-east-1b"]
}

variable "private_subnets" {
  description = "CIDR ranges for private subnets"
  type = list(string)
  default = ["10.0.0.0/19", "10.0.32.0/19"]
}

variable "public_subnets" {
  description = "CIDR ranges for public subnets"
  type = list(string)
  default = ["10.0.64.0/19", "10.0.96.0/19"]
}

// File: main.tf
data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  dns_suffix = data.aws_partition.current.dns_suffix
}

################################################################################
# IAM Role for Service Account (IRSA)
# This is used by the Karpenter controller
################################################################################

locals {
  create_irsa      = var.create && var.create_irsa
  irsa_name        = coalesce(var.irsa_name, "KarpenterIRSA-${var.cluster_name}")
  irsa_policy_name = coalesce(var.irsa_policy_name, local.irsa_name)

  irsa_oidc_provider_url = replace(var.irsa_oidc_provider_arn, "/^(.*provider/)/", "")
}

data "aws_iam_policy_document" "irsa_assume_role" {
  count = local.create_irsa ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.irsa_oidc_provider_arn]
    }

    condition {
      test     = var.irsa_assume_role_condition_test
      variable = "${local.irsa_oidc_provider_url}:sub"
      values   = [for sa in var.irsa_namespace_service_accounts : "system:serviceaccount:${sa}"]
    }

    # https://aws.amazon.com/premiumsupport/knowledge-center/eks-troubleshoot-oidc-and-irsa/?nc1=h_ls
    condition {
      test     = var.irsa_assume_role_condition_test
      variable = "${local.irsa_oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "irsa" {
  count = local.create_irsa ? 1 : 0

  name        = var.irsa_use_name_prefix ? null : local.irsa_name
  name_prefix = var.irsa_use_name_prefix ? "${local.irsa_name}-" : null
  path        = var.irsa_path
  description = var.irsa_description

  assume_role_policy    = data.aws_iam_policy_document.irsa_assume_role[0].json
  max_session_duration  = var.irsa_max_session_duration
  permissions_boundary  = var.irsa_permissions_boundary_arn
  force_detach_policies = true

  tags = merge(var.tags, var.irsa_tags)
}

data "aws_iam_policy_document" "irsa" {
  count = local.create_irsa ? 1 : 0

  statement {
    actions = [
      "ec2:CreateLaunchTemplate",
      "ec2:CreateFleet",
      "ec2:CreateTags",
      "ec2:DescribeLaunchTemplates",
      "ec2:DescribeImages",
      "ec2:DescribeInstances",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeInstanceTypeOfferings",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeSpotPriceHistory",
      "pricing:GetProducts",
    ]

    resources = ["*"]
  }

  statement {
    actions = [
      "ec2:TerminateInstances",
      "ec2:DeleteLaunchTemplate",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "ec2:ResourceTag/${var.irsa_tag_key}"
      values   = [var.cluster_name]
    }
  }

  statement {
    actions = ["ec2:RunInstances"]
    resources = [
      "arn:${local.partition}:ec2:*:${local.account_id}:launch-template/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "ec2:ResourceTag/${var.irsa_tag_key}"
      values   = [var.cluster_name]
    }
  }

  statement {
    actions = ["ec2:RunInstances"]
    resources = [
      "arn:${local.partition}:ec2:*::image/*",
      "arn:${local.partition}:ec2:*:${local.account_id}:instance/*",
      "arn:${local.partition}:ec2:*:${local.account_id}:spot-instances-request/*",
      "arn:${local.partition}:ec2:*:${local.account_id}:security-group/*",
      "arn:${local.partition}:ec2:*:${local.account_id}:volume/*",
      "arn:${local.partition}:ec2:*:${local.account_id}:network-interface/*",
      "arn:${local.partition}:ec2:*:${coalesce(var.irsa_subnet_account_id, local.account_id)}:subnet/*",
    ]
  }

  statement {
    actions   = ["ssm:GetParameter"]
    resources = var.irsa_ssm_parameter_arns
  }

  statement {
    actions   = ["eks:DescribeCluster"]
    resources = ["arn:${local.partition}:eks:*:${local.account_id}:cluster/${var.cluster_name}"]
  }

  statement {
    actions   = ["iam:PassRole"]
    resources = [var.create_iam_role ? aws_iam_role.this[0].arn : var.iam_role_arn]
  }

  dynamic "statement" {
    for_each = local.enable_spot_termination ? [1] : []

    content {
      actions = [
        "sqs:DeleteMessage",
        "sqs:GetQueueUrl",
        "sqs:GetQueueAttributes",
        "sqs:ReceiveMessage",
      ]
      resources = [aws_sqs_queue.this[0].arn]
    }
  }
}

resource "aws_iam_policy" "irsa" {
  count = local.create_irsa ? 1 : 0

  name_prefix = "${local.irsa_policy_name}-"
  path        = var.irsa_path
  description = var.irsa_description
  policy      = data.aws_iam_policy_document.irsa[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "irsa" {
  count = local.create_irsa ? 1 : 0

  role       = aws_iam_role.irsa[0].name
  policy_arn = aws_iam_policy.irsa[0].arn
}

resource "aws_iam_role_policy_attachment" "irsa_additional" {
  for_each = { for k, v in var.policies : k => v if local.create_irsa }

  role       = aws_iam_role.irsa[0].name
  policy_arn = each.value
}

################################################################################
# Node Termination Queue
################################################################################

locals {
  enable_spot_termination = var.create && var.enable_spot_termination

  queue_name = coalesce(var.queue_name, "Karpenter-${var.cluster_name}")
}

resource "aws_sqs_queue" "this" {
  count = local.enable_spot_termination ? 1 : 0

  name                              = local.queue_name
  message_retention_seconds         = 300
  sqs_managed_sse_enabled           = var.queue_managed_sse_enabled ? var.queue_managed_sse_enabled : null
  kms_master_key_id                 = var.queue_kms_master_key_id
  kms_data_key_reuse_period_seconds = var.queue_kms_data_key_reuse_period_seconds

  tags = var.tags
}

data "aws_iam_policy_document" "queue" {
  count = local.enable_spot_termination ? 1 : 0

  statement {
    sid       = "SqsWrite"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.this[0].arn]

    principals {
      type = "Service"
      identifiers = [
        "events.${local.dns_suffix}",
        "sqs.${local.dns_suffix}",
      ]
    }

  }
}

resource "aws_sqs_queue_policy" "this" {
  count = local.enable_spot_termination ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.queue[0].json
}

################################################################################
# Node Termination Event Rules
################################################################################

locals {
  events = {
    health_event = {
      name        = "HealthEvent"
      description = "Karpenter interrupt - AWS health event"
      event_pattern = {
        source      = ["aws.health"]
        detail-type = ["AWS Health Event"]
      }
    }
    spot_interupt = {
      name        = "SpotInterrupt"
      description = "Karpenter interrupt - EC2 spot instance interruption warning"
      event_pattern = {
        source      = ["aws.ec2"]
        detail-type = ["EC2 Spot Instance Interruption Warning"]
      }
    }
    instance_rebalance = {
      name        = "InstanceRebalance"
      description = "Karpenter interrupt - EC2 instance rebalance recommendation"
      event_pattern = {
        source      = ["aws.ec2"]
        detail-type = ["EC2 Instance Rebalance Recommendation"]
      }
    }
    instance_state_change = {
      name        = "InstanceStateChange"
      description = "Karpenter interrupt - EC2 instance state-change notification"
      event_pattern = {
        source      = ["aws.ec2"]
        detail-type = ["EC2 Instance State-change Notification"]
      }
    }
  }
}

resource "aws_cloudwatch_event_rule" "this" {
  for_each = { for k, v in local.events : k => v if local.enable_spot_termination }

  name_prefix   = "${var.rule_name_prefix}${each.value.name}-"
  description   = each.value.description
  event_pattern = jsonencode(each.value.event_pattern)

  tags = merge(
    { "ClusterName" : var.cluster_name },
    var.tags,
  )
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = { for k, v in local.events : k => v if local.enable_spot_termination }

  rule      = aws_cloudwatch_event_rule.this[each.key].name
  target_id = "KarpenterInterruptionQueueTarget"
  arn       = aws_sqs_queue.this[0].arn
}

################################################################################
# Node IAM Role
# This is used by the nodes launched by Karpenter
################################################################################

locals {
  create_iam_role = var.create && var.create_iam_role

  iam_role_name          = coalesce(var.iam_role_name, "Karpenter-${var.cluster_name}")
  iam_role_policy_prefix = "arn:${local.partition}:iam::aws:policy"
  cni_policy             = var.cluster_ip_family == "ipv6" ? "${local.iam_role_policy_prefix}/AmazonEKS_CNI_IPv6_Policy" : "${local.iam_role_policy_prefix}/AmazonEKS_CNI_Policy"
}

data "aws_iam_policy_document" "assume_role" {
  count = local.create_iam_role ? 1 : 0

  statement {
    sid     = "EKSNodeAssumeRole"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.${local.dns_suffix}"]
    }
  }
}

resource "aws_iam_role" "this" {
  count = local.create_iam_role ? 1 : 0

  name        = var.iam_role_use_name_prefix ? null : local.iam_role_name
  name_prefix = var.iam_role_use_name_prefix ? "${local.iam_role_name}-" : null
  path        = var.iam_role_path
  description = var.iam_role_description

  assume_role_policy    = data.aws_iam_policy_document.assume_role[0].json
  max_session_duration  = var.iam_role_max_session_duration
  permissions_boundary  = var.iam_role_permissions_boundary
  force_detach_policies = true

  tags = merge(var.tags, var.iam_role_tags)
}

# Policies attached ref https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/eks_node_group
resource "aws_iam_role_policy_attachment" "this" {
  for_each = { for k, v in toset(compact([
    "${local.iam_role_policy_prefix}/AmazonEKSWorkerNodePolicy",
    "${local.iam_role_policy_prefix}/AmazonEC2ContainerRegistryReadOnly",
    var.iam_role_attach_cni_policy ? local.cni_policy : "",
  ])) : k => v if local.create_iam_role }

  policy_arn = each.value
  role       = aws_iam_role.this[0].name
}

resource "aws_iam_role_policy_attachment" "additional" {
  for_each = { for k, v in var.iam_role_additional_policies : k => v if local.create_iam_role }

  policy_arn = each.value
  role       = aws_iam_role.this[0].name
}

################################################################################
# Node IAM Instance Profile
# This is used by the nodes launched by Karpenter
################################################################################

locals {
  external_role_name = try(replace(var.iam_role_arn, "/^(.*role/)/", ""), null)
}

resource "aws_iam_instance_profile" "this" {
  count = var.create && var.create_instance_profile ? 1 : 0

  name        = var.iam_role_use_name_prefix ? null : local.iam_role_name
  name_prefix = var.iam_role_use_name_prefix ? "${local.iam_role_name}-" : null
  path        = var.iam_role_path
  role        = var.create_iam_role ? aws_iam_role.this[0].name : local.external_role_name

  tags = merge(var.tags, var.iam_role_tags)
}

// File: outputs.tf
################################################################################
# IAM Role for Service Account (IRSA)
################################################################################

output "irsa_name" {
  description = "The name of the IAM role for service accounts"
  value       = try(aws_iam_role.irsa[0].name, null)
}

output "irsa_arn" {
  description = "The Amazon Resource Name (ARN) specifying the IAM role for service accounts"
  value       = try(aws_iam_role.irsa[0].arn, null)
}

output "irsa_unique_id" {
  description = "Stable and unique string identifying the IAM role for service accounts"
  value       = try(aws_iam_role.irsa[0].unique_id, null)
}

################################################################################
# Node Termination Queue
################################################################################

output "queue_arn" {
  description = "The ARN of the SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_name" {
  description = "The name of the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "queue_url" {
  description = "The URL for the created Amazon SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

################################################################################
# Node Termination Event Rules
################################################################################

output "event_rules" {
  description = "Map of the event rules created and their attributes"
  value       = aws_cloudwatch_event_rule.this
}

################################################################################
# Node IAM Role
################################################################################

output "role_name" {
  description = "The name of the IAM role"
  value       = try(aws_iam_role.this[0].name, null)
}

output "role_arn" {
  description = "The Amazon Resource Name (ARN) specifying the IAM role"
  value       = try(aws_iam_role.this[0].arn, var.iam_role_arn)
}

output "role_unique_id" {
  description = "Stable and unique string identifying the IAM role"
  value       = try(aws_iam_role.this[0].unique_id, null)
}

################################################################################
# Node IAM Instance Profile
################################################################################

output "instance_profile_arn" {
  description = "ARN assigned by AWS to the instance profile"
  value       = try(aws_iam_instance_profile.this[0].arn, null)
}

output "instance_profile_id" {
  description = "Instance profile's ID"
  value       = try(aws_iam_instance_profile.this[0].id, null)
}

output "instance_profile_name" {
  description = "Name of the instance profile"
  value       = try(aws_iam_instance_profile.this[0].name, null)
}

output "instance_profile_unique" {
  description = "Stable and unique string identifying the IAM instance profile"
  value       = try(aws_iam_instance_profile.this[0].unique_id, null)
}

// File: variables.tf
variable "create" {
  description = "Determines whether to create EKS managed node group or not"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

variable "cluster_name" {
  description = "The name of the EKS cluster"
  type        = string
  default     = ""
}

################################################################################
# IAM Role for Service Account (IRSA)
################################################################################

variable "create_irsa" {
  description = "Determines whether an IAM role for service accounts is created"
  type        = bool
  default     = true
}

variable "irsa_name" {
  description = "Name of IAM role for service accounts"
  type        = string
  default     = null
}

variable "irsa_policy_name" {
  description = "Name of IAM policy for service accounts"
  type        = string
  default     = null
}

variable "irsa_use_name_prefix" {
  description = "Determines whether the IAM role for service accounts name (`irsa_name`) is used as a prefix"
  type        = bool
  default     = true
}

variable "irsa_path" {
  description = "Path of IAM role for service accounts"
  type        = string
  default     = "/"
}

variable "irsa_description" {
  description = "IAM role for service accounts description"
  type        = string
  default     = "Karpenter IAM role for service account"
}

variable "irsa_max_session_duration" {
  description = "Maximum API session duration in seconds between 3600 and 43200"
  type        = number
  default     = null
}

variable "irsa_permissions_boundary_arn" {
  description = "Permissions boundary ARN to use for IAM role for service accounts"
  type        = string
  default     = null
}

variable "irsa_tags" {
  description = "A map of additional tags to add the the IAM role for service accounts"
  type        = map(any)
  default     = {}
}

variable "policies" {
  description = "Policies to attach to the IAM role in `{'static_name' = 'policy_arn'}` format"
  type        = map(string)
  default     = {}
}

variable "irsa_tag_key" {
  description = "Tag key (`{key = value}`) applied to resources launched by Karpenter through the Karpenter provisioner"
  type        = string
  default     = "karpenter.sh/discovery"
}

variable "irsa_ssm_parameter_arns" {
  description = "List of SSM Parameter ARNs that contain AMI IDs launched by Karpenter"
  type        = list(string)
  # https://github.com/aws/karpenter/blob/ed9473a9863ca949b61b9846c8b9f33f35b86dbd/pkg/cloudprovider/aws/ami.go#L105-L123
  default = ["arn:aws:ssm:*:*:parameter/aws/service/*"]
}

variable "irsa_subnet_account_id" {
  description = "Account ID of where the subnets Karpenter will utilize resides. Used when subnets are shared from another account"
  type        = string
  default     = ""
}

variable "irsa_oidc_provider_arn" {
  description = "OIDC provider arn used in trust policy for IAM role for service accounts"
  type        = string
  default     = ""
}

variable "irsa_namespace_service_accounts" {
  description = "List of `namespace:serviceaccount`pairs to use in trust policy for IAM role for service accounts"
  type        = list(string)
  default     = ["karpenter:karpenter"]
}

variable "irsa_assume_role_condition_test" {
  description = "Name of the [IAM condition operator](https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_policies_elements_condition_operators.html) to evaluate when assuming the role"
  type        = string
  default     = "StringEquals"
}

################################################################################
# Node Termination Queue
################################################################################

variable "enable_spot_termination" {
  description = "Determines whether to enable native spot termination handling"
  type        = bool
  default     = true
}

variable "queue_name" {
  description = "Name of the SQS queue"
  type        = string
  default     = null
}

variable "queue_managed_sse_enabled" {
  description = "Boolean to enable server-side encryption (SSE) of message content with SQS-owned encryption keys"
  type        = bool
  default     = true
}

variable "queue_kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK"
  type        = string
  default     = null
}

variable "queue_kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling AWS KMS again"
  type        = number
  default     = null
}

################################################################################
# Node IAM Role & Instance Profile
################################################################################

variable "create_iam_role" {
  description = "Determines whether an IAM role is created or to use an existing IAM role"
  type        = bool
  default     = true
}

variable "cluster_ip_family" {
  description = "The IP family used to assign Kubernetes pod and service addresses. Valid values are `ipv4` (default) and `ipv6`"
  type        = string
  default     = null
}

variable "iam_role_arn" {
  description = "Existing IAM role ARN for the IAM instance profile. Required if `create_iam_role` is set to `false`"
  type        = string
  default     = null
}

variable "iam_role_name" {
  description = "Name to use on IAM role created"
  type        = string
  default     = null
}

variable "iam_role_use_name_prefix" {
  description = "Determines whether the IAM role name (`iam_role_name`) is used as a prefix"
  type        = bool
  default     = true
}

variable "iam_role_path" {
  description = "IAM role path"
  type        = string
  default     = "/"
}

variable "iam_role_description" {
  description = "Description of the role"
  type        = string
  default     = null
}

variable "iam_role_max_session_duration" {
  description = "Maximum API session duration in seconds between 3600 and 43200"
  type        = number
  default     = null
}

variable "iam_role_permissions_boundary" {
  description = "ARN of the policy that is used to set the permissions boundary for the IAM role"
  type        = string
  default     = null
}

variable "iam_role_attach_cni_policy" {
  description = "Whether to attach the `AmazonEKS_CNI_Policy`/`AmazonEKS_CNI_IPv6_Policy` IAM policy to the IAM IAM role. WARNING: If set `false` the permissions must be assigned to the `aws-node` DaemonSet pods via another method or nodes will not be able to join the cluster"
  type        = bool
  default     = true
}

variable "iam_role_additional_policies" {
  description = "Additional policies to be added to the IAM role"
  type        = list(string)
  default     = []
}

variable "iam_role_tags" {
  description = "A map of additional tags to add to the IAM role created"
  type        = map(string)
  default     = {}
}

################################################################################
# Node IAM Instance Profile
################################################################################

variable "create_instance_profile" {
  description = "Whether to create an IAM instance profile"
  type        = bool
  default     = true
}

################################################################################
# Event Bridge Rules
################################################################################

variable "rule_name_prefix" {
  description = "Prefix used for all event bridge rules"
  type        = string
  default     = "Karpenter"
}

// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.47"
    }
  }
}

// File: _global.tf
data "aws_caller_identity" "current" {}

variable "name_prefix" {
  description = "A prefix that will be used on all named resources."
  type        = string
  default     = "pippi-"

  validation {
    condition     = length(regexall("^[a-zA-Z-]*$", var.name_prefix)) > 0
    error_message = "`name_prefix` must satisfy pattern `^[a-zA-Z-]+$`."
  }
}

variable "default_tags" {
  description = "A map of default tags, that will be applied to all resources applicable."
  type        = map(string)
  default     = {}
}

locals {
  name_prefix = var.name_prefix
  default_tags = merge(var.default_tags, {
    tf-module : "pippi.io/aws-ecr"
    tf-workspace = terraform.workspace
  })

  account_id = data.aws_caller_identity.current.account_id
}

// File: ecr.tf
# kics-scan ignore-block
resource "aws_ecr_repository" "this" {
  for_each = var.private_repositories

  name                 = each.key
  image_tag_mutability = each.value.image_tag_mutability != null ? each.value.image_tag_mutability : "MUTABLE"

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.ecr["private"].arn
  }

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.default_tags, {
    "Name" = each.key
  })
}

resource "aws_ecr_repository_policy" "this" {
  for_each = aws_ecr_repository.this

  repository = each.value.name
  policy     = data.aws_iam_policy_document.private[each.key].json
}

resource "aws_ecrpublic_repository" "this" {
  for_each = var.public_repositories

  repository_name = each.key

  catalog_data {
    about_text        = each.value.about
    architectures     = each.value.architectures
    description       = each.value.description
    logo_image_blob   = each.value.logo_image_blob
    operating_systems = each.value.operating_systems
    usage_text        = each.value.usage_text
  }

  tags = merge(local.default_tags, {
    "Name" = each.key
  })
}

resource "aws_ecrpublic_repository_policy" "this" {
  for_each = aws_ecrpublic_repository.this

  repository_name = each.value.repository_name
  policy          = data.aws_iam_policy_document.public[each.key].json
}

// File: iam.tf
# kics-scan ignore-block
resource "aws_iam_user" "artifact_user" {
  for_each = local.create_iam_users

  name = "${local.name_prefix}${each.key}"
  path = "/artifact/"

  tags = merge(local.default_tags, {
    "Name" = "${local.name_prefix}${each.key}"
  })
}

resource "aws_iam_access_key" "artifact_user" {
  for_each = aws_iam_user.artifact_user

  user = each.value.name
}

# kics-scan ignore-block
resource "aws_iam_user_policy" "artifact_user" {
  for_each = aws_iam_user.artifact_user

  name   = "ECR"
  user   = each.value.name
  policy = try(data.aws_iam_policy_document.artifact_user_private[each.key].json, data.aws_iam_policy_document.artifact_user_public[each.key].json)
}

data "aws_iam_policy_document" "artifact_user_private" {
  for_each = aws_ecr_repository.this

  statement {
    sid       = "AllowECR"
    actions   = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:CompleteLayerUpload",
      "ecr:GetDownloadUrlForLayer",
      "ecr:InitiateLayerUpload",
      "ecr:PutImage",
      "ecr:UploadLayerPart"
    ]
    resources = [
      each.value.arn
    ]
  }

  statement {
    sid       = "AllowECRAuthorization" # needed to login to ecr
    actions   = [
      "ecr:GetAuthorizationToken"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "artifact_user_public" {
  for_each = aws_ecrpublic_repository.this

  statement {
    sid       = "AllowECRPublic"
    actions   = [
      "ecr-public:BatchCheckLayerAvailability",
      "ecr-public:BatchGetImage",
      "ecr-public:CompleteLayerUpload",
      "ecr-public:GetDownloadUrlForLayer",
      "ecr-public:InitiateLayerUpload",
      "ecr-public:PutImage",
      "ecr-public:UploadLayerPart",
    ]
    resources = [
      each.value.arn
    ]
  }

  statement {
    sid       = "AllowECRPublicAuthorization" # needed to login to ecr
    actions   = [
      "ecr-public:GetAuthorizationToken",
      "sts:GetServiceBearerToken"
    ]
    resources = ["*"]
  }
}

// File: kms.tf
data "aws_iam_policy_document" "kms" {
  for_each = length(var.private_repositories) > 0 ? toset(["private"]) : []

  statement {
    resources = ["*"]
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.id}:root"]
    }
  }
}

# kics-scan ignore-block
resource "aws_kms_key" "ecr" {
  for_each = data.aws_iam_policy_document.kms

  description         = "KMS CMK used by ecr"
  enable_key_rotation = true
  policy              = each.value.json

  tags = merge(local.default_tags, {
    "Name" = "${local.name_prefix}ecr-kms"
  })
}

// File: main.tf
locals {
  private_repo_pull_arns = { for k, repo in var.private_repositories : k => concat(
    [for index, account in repo.pull_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.pull_role_arns : role]
  ) }

  private_repo_push_arns = { for k, repo in var.private_repositories : k => concat(
    [for index, account in repo.push_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.push_role_arns : role]
  ) }

  public_repo_push_arns = { for k, repo in var.public_repositories : k => concat(
    [for index, account in repo.push_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.push_role_arns : role]
  ) }

  global_pull_account_arns = concat([for ac in var.global_pull_accounts : "arn:aws:iam::${ac}:root"], ["arn:aws:iam::${local.account_id}:root"])
  global_push_account_arns = concat([for ac in var.global_push_accounts : "arn:aws:iam::${ac}:root"], ["arn:aws:iam::${local.account_id}:root"])

  create_iam_users = toset([for k, repo in merge(var.private_repositories, var.public_repositories) : k if repo.create_iam_user])
}

// File: output.tf
output "private_repositories" {
  value       = aws_ecr_repository.this
  description = "List of private ECR repositories"
}

output "public_repositories" {
  value       = aws_ecrpublic_repository.this
  description = "List of public ECR repositories"
}

output "iam_users" {
  value = {
    for key, user in aws_iam_user.artifact_user :
    user.name => {
      user_arn          = user.arn
      access_key_id     = aws_iam_access_key.artifact_user[key].id
      secret_access_key = aws_iam_access_key.artifact_user[key].secret
    }
  }
  sensitive   = true
  description = "List of IAM users"
}

// File: policy.tf
data "aws_iam_policy_document" "private" {
  for_each = var.private_repositories

  statement {
    sid = "PullPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_pull_account_arns, local.private_repo_pull_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImageScanFindings",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:GetLifecyclePolicy",
      "ecr:GetLifecyclePolicyPreview",
      "ecr:GetRepositoryPolicy",
      "ecr:ListImages",
      "ecr:ListTagsForResource",
    ]
  }

  statement {
    sid = "PushPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_push_account_arns, local.private_repo_push_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
    ]
  }
}

data "aws_iam_policy_document" "public" {
  for_each = var.public_repositories

  statement {
    sid = "PushPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_push_account_arns, local.public_repo_push_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
    ]
  }
}

// File: variables.tf
variable "private_repositories" {
  type = map(object({
    image_tag_mutability = optional(string)
    pull_accounts        = optional(list(string), [])
    pull_role_arns       = optional(list(string), [])
    push_accounts        = optional(list(string), [])
    push_role_arns       = optional(list(string), [])
    create_iam_user      = optional(bool, false)
  }))
  description = "List of private repositories that should be created"
  default     = {}
}

variable "public_repositories" {
  type = map(object({
    about             = optional(string)
    architectures     = optional(list(string))
    description       = optional(string)
    logo_image_blob   = optional(string)
    operating_systems = optional(list(string))
    usage_text        = optional(string)
    push_accounts     = optional(list(string), [])
    push_role_arns    = optional(list(string), [])
    create_iam_user   = optional(bool, false)
  }))
  description = "List of public repositories that should be created"
  default     = {}
}

variable "global_pull_accounts" {
  type        = list(string)
  description = "List of accounts that can pull from all the private repositories"
  default     = []
}

variable "global_push_accounts" {
  type        = list(string)
  description = "List of accounts that can push to all the repositories"
  default     = []
}

// File: version.tf
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

// File: cognito.tf
resource "aws_cognito_user_pool" "box_things_pool" {
  name = "box_things"

  alias_attributes = [
    "email"
  ]

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  password_policy {
    minimum_length                   = 8
    require_uppercase                = true
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  schema {
    name                = "email"
    attribute_data_type = "String"
    mutable             = false
    required            = true
    string_attribute_constraints {
      max_length = "2048"
      min_length = "0"
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  mfa_configuration = "OFF"

  auto_verified_attributes = ["email"]

  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
    email_subject        = "Confirm your account"
    email_message        = "To confirm your account please click on the link. {####}"
  }

}

data "aws_iam_policy_document" "instance_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cognito-idp.amazonaws.com"]
    }
  }
}

resource "aws_cognito_user_pool_client" "box_things_client" {
  access_token_validity = 60
  id_token_validity     = 60
  name                  = "box_things_client"
  callback_urls = [
    "https://www.google.com",
  ]
  explicit_auth_flows = [
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
  ]
  logout_urls = [
    "https://www.google.com",
  ]
  supported_identity_providers = [
    "COGNITO",
  ]
  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  user_pool_id = "${aws_cognito_user_pool.box_things_pool.id}"
}

output cognito_user_pool_arn {
  value = "${aws_cognito_user_pool.box_things_pool.arn}"
}

