    "10.0.104.0/24",
    "10.0.105.0/24",
    "10.0.106.0/24"
  ]

  enable_dns_hostnames = true
  enable_dns_support   = true

  enable_nat_gateway = true
  single_nat_gateway = true
}

// File: main.tf
# main.tf

variable "env" {
  default = "prod"
}

resource "random_integer" "randomy" {
  min = 100000
  max = 999999
}

resource "aws_s3_bucket" "bucket" {
  bucket = "terraform-example-5-${random_integer.randomy.result}"
  tags = {
    Ex  = "example-5"
    Env = var.env == "prod" ? "Production" : "Development"
  }
}

variable "for_map" {
  default = {
    "one" = 1
    "two" = 2
  }
}

resource "aws_s3_object" "object" {
  for_each = var.for_map
  key      = "tf-example-5-object-${each.value}"
  bucket   = aws_s3_bucket.bucket.id
  content  = "This file is from ${each.key}"
  tags = {
    Obj = "${upper("example-5")}-${each.key}"
    Env = var.env == "prod" ? "Production" : "Development"
  }
}

// File: providers.tf
terraform {
  required_version = "~>1.4"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~>5.20"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

// File: locals.tf
# Default AWS Manage Rules
locals {
  default_aws_managed_rules = var.enable_default_aws_managed_rules == true ? {
    root-account-mfa-enabled = {
      description      = "Checks if the root user of your AWS account requires multi-factor authentication for console sign-in."
      identifier       = "ROOT_ACCOUNT_MFA_ENABLED"
      input_parameters = {}
    }
    iam-root-access-key-check = {
      description      = "Checks if the root user access key is available."
      identifier       = "IAM_ROOT_ACCESS_KEY_CHECK"
      input_parameters = {}
    }
    iam-user-mfa-enabled = {
      description      = "Checks if the AWS Identity and Access Management (IAM) users have multi-factor authentication (MFA) enabled."
      identifier       = "IAM_USER_MFA_ENABLED"
      input_parameters = {}
    }
  } : {}

  aws_managed_rule_required_tags = var.required_tags_enabled == true ? {
    required-tags = {
      description      = "Checks if your resources have the tags that you specify."
      identifier       = "REQUIRED_TAGS"
      input_parameters = var.required_tags
    }
  } : {}

  # Merge the default rules with the user defined rules
  aws_managed_rules = merge(var.aws_managed_rules, local.default_aws_managed_rules, local.aws_managed_rule_required_tags)

}

// File: main.tf
# AWS Managed rules could be a combination of Global and Regional rules for list of available rules check
# https://docs.aws.amazon.com/config/latest/developerguide/managed-rules-by-aws-config.html
resource "aws_config_config_rule" "aws_managed_rules" {
  for_each = local.aws_managed_rules != null ? local.aws_managed_rules : {}

  name        = each.key
  description = each.value.description

  source {
    owner             = "AWS"
    source_identifier = each.value.identifier
  }

  input_parameters = length(each.value.input_parameters) > 0 ? jsonencode(each.value.input_parameters) : null

  tags = local.common_tags
}

# AWS Managed rules could be a combination of Global and Regional rules for list of available rules check
# https://docs.aws.amazon.com/config/latest/developerguide/managed-rules-by-aws-config.html
resource "aws_config_config_rule" "custom_managed_rules" {
  for_each = var.custom_managed_rules != null ? var.custom_managed_rules : {}

  name        = each.key
  description = each.value.description

  scope {
    compliance_resource_id    = lookup(each.value.scope, "compliance_resource_id", null)
    compliance_resource_types = lookup(each.value.scope, "compliance_resource_types", null)
    tag_key                   = lookup(each.value.scope, "tag_key", null)
    tag_value                 = lookup(each.value.scope, "tag_value", null)
  }

  source {
    owner = "CUSTOM_POLICY"
    dynamic "source_detail" {
      for_each = each.value.source.source_detail != null ? [each.value.source.source_detail] : []
      content {
        maximum_execution_frequency = source_detail.value.message_type == "ScheduledNotification" ? source_detail.value.maximum_execution_frequency : null
        # https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/config_config_rule#message_type
        message_type = source_detail.value.message_type
      }
    }

    dynamic "custom_policy_details" {
      for_each = each.value.source.custom_policy_details != null ? [each.value.source.custom_policy_details] : []
      content {
        enable_debug_log_delivery = lookup(custom_policy_details.value, "enable_debug_log_delivery", null)
        policy_runtime            = custom_policy_details.value.policy_runtime
        policy_text               = custom_policy_details.value.policy_text
      }
    }
  }

  tags = local.common_tags
}

// File: tags.tf
locals {
  common_tags = merge(var.input_tags, {
    "ModuleSourceRepo" = "github.com/StratusGrid/terraform-aws-config-rules"
  })
}

// File: variables.tf
variable "enable_default_aws_managed_rules" {
  description = "True/False to add default Config Rules. Default is true"
  type        = bool
  default     = true
}

variable "required_tags_enabled" {
  description = "True/False to add RequiredTags to Config. Default is false"
  type        = bool
  default     = false
}

variable "required_tags" {
  description = "Map of tag keys, and optionally values, that are required."
  type        = map(any)
  default     = {}
}

variable "input_tags" {
  description = "Map of tags to apply to resources"
  type        = map(any)
  default = {
    Developer   = "StratusGrid"
    Provisioner = "Terraform"
  }
}

variable "aws_managed_rules" {
  description = <<-DOC
    A list of AWS Managed Rules that should be enabled on the account.

    See the following for a list of possible rules to enable:
    https://docs.aws.amazon.com/config/latest/developerguide/managed-rules-by-aws-config.html
  DOC
  type = map(object({
    description      = string
    identifier       = string
    input_parameters = any
  }))
  default = {}
}

variable "custom_managed_rules" {
  description = <<-DOC
    A list of AWS Managed Custom Rules that should be enabled on the account.

    Reference
    https://docs.aws.amazon.com/config/latest/developerguide/evaluate-config_develop-rules.html
  DOC
  type        = map(any)
  default     = {}
}

// File: versions.tf
terraform {
  required_version = ">= v1.6.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.57.0"
    }
  }
}

// File: data.tf
data "aws_availability_zones" "available" {
  state = "available"
}

// File: locals.tf
locals {
  availability_zone           = data.aws_availability_zones.available.names[0]
  secondary_availability_zone = data.aws_availability_zones.available.names[1]
  vpc_cidr_block              = "10.32.0.0/20"
}

// File: outputs.tf
output "vpc" {
  description = "The dev VPC"
