// File: xray_encryption_config.tf
#---------------------------------------------------
# AWS xray encryption config
#---------------------------------------------------
resource "aws_xray_encryption_config" "xray_encryption_config" {
  count = var.enable_xray_encryption_config ? 1 : 0

  type = var.xray_encryption_config_type

  key_id = var.xray_encryption_config_key_id

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: xray_group.tf
#---------------------------------------------------
# AWS xray group
#---------------------------------------------------
resource "aws_xray_group" "xray_group" {
  count = var.enable_xray_group ? 1 : 0

  group_name        = var.xray_group_name != "" ? var.xray_group_name : "${lower(var.name)}-xray-group-${lower(var.environment)}"
  filter_expression = var.xray_group_filter_expression

  tags = merge(
    {
      Name = var.xray_group_name != "" ? var.xray_group_name : "${lower(var.name)}-xray-group-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
