// File: main.tf
# Create S3 bucket for storing uploaded files
resource "aws_s3_bucket" "prodioslabsbucket" {
  bucket = "my-tf-example-bucket"

    tags = {
    Name = "App Uploaded Files"
  }
}

resource "aws_s3_bucket_ownership_controls" "example" {
  bucket = aws_s3_bucket.prodioslabsbucket.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "pl-acl" {
  depends_on = [aws_s3_bucket_ownership_controls.example]

  bucket = aws_s3_bucket.prodioslabsbucket.id
  acl    = "private"
}

# IAM role for EC2 instance with access to S3 bucket
resource "aws_iam_role" "ec2_role" {
  name = "app-ec2-role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "s3_access" {
  role       = aws_iam_role.ec2_role.id
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

// File: output.tf
output "ec2_role" {
  value = aws_iam_role.ec2_role.name
}

output "bucket_domain_name" {
  value = aws_s3_bucket.prodioslabsbucket.bucket_domain_name
}

// File: main.tf
# Setting up the VPC
resource "aws_vpc" "ecs_network" {
  cidr_block       = "10.0.0.0/16"
  instance_tenancy = "default"

  tags = merge(
    { origin = "dragondrop-compute-module" },
    var.tags,
  )
}

# Add Security Group + Rules to the VPC
resource "aws_security_group" "ecs_fargate_sg" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Allow unrestricted outbound egress"
  vpc_id      = aws_vpc.ecs_network.id

  tags = merge(
    { origin = "dragondrop-compute-module" },
    var.tags,
  )
}

resource "aws_security_group_rule" "egress" {
  security_group_id = aws_security_group.ecs_fargate_sg.id
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
}


# Routes table definition to internet
resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.ecs_network.id

  tags = merge(
    { origin = "dragondrop-compute-module" },
    var.tags,
  )
}

resource "aws_route_table" "public_subnets_route_table" {
  vpc_id = aws_vpc.ecs_network.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.internet_gateway.id
  }

  tags = merge(
    { origin = "dragondrop-compute-module", name = "ecs fargate routes table" },
    var.tags,
  )
}

# Creating a Public Subnet with access to the internet
resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.ecs_network.id
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = true

  tags = merge(
    { origin = "dragondrop-compute-module", name = "ecs fargate routes table" },
    var.tags,
  )
}

resource "aws_route_table_association" "link_public_access_route_table" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_subnets_route_table.id
}

// File: outputs.tf
output "security_group" {
  description = "Security group for ECS fargate task networking."
  value       = aws_security_group.ecs_fargate_sg.id
}

output "subnet" {
  description = "Subnet within which the ECS Fargate Task is placed."
  value       = aws_subnet.public_subnet.id
}

// File: variables.tf
variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

// File: main.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.7.0"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  for_each = var.vpc

  cidr_block           = each.value.cidr_block
  enable_dns_support   = each.value.enable_dns
  enable_dns_hostnames = each.value.enable_dns_hostnames

  tags = merge(
    var.tags,
    {
      "Name" = "vpc-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_subnet" "main" {
  for_each = {
    for key, value in var.subnets : key => value
  }

  vpc_id            = aws_vpc.main[each.value.vpc_name].id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = merge(
    var.tags,
    {
      "Name" = "sn-${each.key}-${each.value.availability_zone}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_internet_gateway" "main" {
  for_each = var.internet_gateway

  vpc_id = aws_vpc.main[each.value.vpc_name].id

  tags = merge(
    var.tags,
    {
      "Name" = "igw-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_eip" "main" {
  for_each = var.nat_gateway

  domain = "vpc"
  tags = merge(
    var.tags,
    {
      "Name" = "eip-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_nat_gateway" "main" {
  depends_on = [aws_internet_gateway.main]
  for_each   = var.nat_gateway

  allocation_id = aws_eip.main[each.key].id
  subnet_id     = aws_subnet.main[each.value.subnet_name].id

  tags = merge(
    var.tags,
    {
      "Name" = "ngw-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_route_table" "main" {
  for_each = var.route_tables

  vpc_id = aws_vpc.main[each.value.vpc_name].id

  dynamic "route" {
    for_each = each.value.routes

    content {
      cidr_block     = route.value.cidr_block
      gateway_id     = route.value.use_igw ? aws_internet_gateway.main[route.value.igw_name].id : null
      nat_gateway_id = route.value.use_ngw ? aws_nat_gateway.main[route.value.ngw_name].id : null
      # network_interface_id      = route.value.use_ec2ni ? aws_network_interface.ec2ni[each.key].id : route.value.network_interface_id
      # vpc_peering_connection_id = route.value.use_vpcpc ? aws_vpc_peering_connection.vpcpc[each.key].id : route.value.vpc_peering_connection_id
      # vpc_endpoint_id           = route.value.use_vpce ? aws_vpc_endpoint.vpce[each.key].id : route.value.vpc_endpoint_id
    }
  }

  tags = merge(
    var.tags,
    {
      "Name" = "rt-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_route_table_association" "main" {
  for_each = var.route_table_associations

  subnet_id      = aws_subnet.main[each.value.subnet_name].id
  route_table_id = aws_route_table.main[each.value.route_table_name].id
}

resource "aws_security_group" "main" {
  for_each = var.security_groups

  description = "Security group for ${each.value.vpc_name} VPC"

  vpc_id = aws_vpc.main[each.value.vpc_name].id

  tags = merge(
    var.tags,
    {
      "Name" = "sg-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_vpc_security_group_ingress_rule" "main" {
  for_each = {
    for sg in flatten([
      for sg_name, sg_config in var.security_groups :
      [for rule_name, rule_config in sg_config.ingress :
        {
          sg_name     = sg_name
          rule_name   = rule_name
          rule_config = rule_config
      }]
    ]) : "${sg.sg_name}.${sg.rule_name}" => sg
  }

  security_group_id = aws_security_group.main[each.value.sg_name].id

  cidr_ipv4                    = try(each.value.rule_config.cidr_ipv4, null)
  from_port                    = each.value.rule_config.from_port
  to_port                      = each.value.rule_config.to_port
  ip_protocol                  = each.value.rule_config.protocol
  referenced_security_group_id = try(aws_security_group.main[each.value.rule_config.security_group_name].id, null)
}

resource "aws_vpc_security_group_egress_rule" "main" {
  for_each = {
    for sg in flatten([
      for sg_name, sg_config in var.security_groups :
      [for rule_name, rule_config in sg_config.egress :
        {
          sg_name     = sg_name
          rule_name   = rule_name
          rule_config = rule_config
      }]
    ]) : "${sg.sg_name}.${sg.rule_name}" => sg
  }

  security_group_id = aws_security_group.main[each.value.sg_name].id

  cidr_ipv4                    = try(each.value.rule_config.cidr_ipv4, null)
  from_port                    = each.value.rule_config.from_port
  to_port                      = each.value.rule_config.to_port
  ip_protocol                  = each.value.rule_config.protocol
  referenced_security_group_id = try(aws_security_group.main[each.value.rule_config.security_group_name].id, null)

}

resource "aws_default_security_group" "default" {
  for_each = var.vpc

  vpc_id = aws_vpc.main[each.key].id

  ingress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

// File: variables.tf
variable "region" {
  description = "AWS region"
  default     = "eu-west-1"
}

variable "vpc" {
  description = "VPC configuration"
  type = map(object({
    cidr_block           = string
    enable_dns           = optional(bool, true)
    enable_dns_hostnames = optional(bool, false)
  }))
  default = {}
}

variable "subnets" {
  description = "Subnet configuration"
  type = map(object({
    vpc_name          = string
    cidr_block        = string
    availability_zone = string
  }))
  default = {}
}

variable "internet_gateway" {
  description = "Internet gateway configuration"
  type = map(object({
    vpc_name = string
  }))
  default = {}
}

variable "nat_gateway" {
  description = "NAT gateway configuration"
  type = map(object({
    vpc_name    = string
    subnet_name = string
  }))
  default = {}
}

variable "route_tables" {
  description = "Route table configuration"
  type = map(object({
    vpc_name = string
    routes : list(object({
      cidr_block = string
      use_igw    = optional(bool, true)
      igw_name   = optional(string, "")
      use_ngw    = optional(bool, false)
      ngw_name   = optional(string, "")
      # use_ec2ni  = optional(bool, false)
      # use_vpcpc  = optional(bool, false)
      # use_vpce   = optional(bool, false)
    }))
  }))
  default = {}
}

variable "route_table_associations" {
  description = "Route table association configuration"
  type = map(object({
    subnet_name      = string
    route_table_name = string
  }))
  default = {}
}

variable "security_groups" {
  type = map(object({
    vpc_name = string
    ingress = map(object({
      from_port           = number
      to_port             = number
      protocol            = string
      cidr_ipv4           = optional(string)
      security_group_name = optional(string)
    }))
    egress = map(object({
      from_port           = number
      to_port             = number
      protocol            = string
      cidr_ipv4           = optional(string)
      security_group_name = optional(string)
    }))
  }))
  default = {}
}

variable "tags" {
  description = "Tags for resources"
  type        = map(string)
  default = {
    environment = "Dev"
    managedBy   = "Terraform"
  }
}

// File: acm_certificate.tf
#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate" {
  count = var.enable_acm_certificate && !var.enable_acm_certificate_private_ca && !var.enable_import_existing_certificate ? 1 : 0

  domain_name       = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
  validation_method = upper(var.acm_certificate_validation_method)

  subject_alternative_names = var.acm_certificate_subject_alternative_names

  dynamic "options" {
    iterator = options
    for_each = var.acm_certificate_options

    content {
      certificate_transparency_logging_preference = lookup(options.value, "certificate_transparency_logging_preference", null)
    }
  }

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate for private CA
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate_private_ca" {
  count = var.enable_acm_certificate_private_ca && !var.enable_acm_certificate && !var.enable_import_existing_certificate ? 1 : 0

  domain_name               = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
  certificate_authority_arn = var.acm_certificate_certificate_authority_arn

  subject_alternative_names = var.acm_certificate_subject_alternative_names

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate for exististing certificate
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate_exist" {
  count = var.enable_import_existing_certificate && !var.enable_acm_certificate && !var.enable_acm_certificate_private_ca ? 1 : 0

  private_key       = var.acm_certificate_private_key
  certificate_body  = var.acm_certificate_certificate_body
  certificate_chain = var.acm_certificate_certificate_chain

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: acm_certificate_validation.tf
#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate validation
#---------------------------------------------------
resource "aws_acm_certificate_validation" "acm_certificate_validation" {
  count = var.enable_acm_certificate_validation ? 1 : 0

  certificate_arn = var.acm_certificate_validation_certificate_arn

  validation_record_fqdns = var.acm_certificate_validation_record_fqdns

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.acm_certificate_validation_timeouts)) > 0 ? [var.acm_certificate_validation_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: acmpca_certificate_authority.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (ACM PCA Certificate Authorities)
#---------------------------------------------------
resource "aws_acmpca_certificate_authority" "acmpca_certificate_authority" {
  count = var.enable_acmpca_certificate_authority ? 1 : 0

  enabled = var.acmpca_certificate_authority_enabled

  permanent_deletion_time_in_days = var.acmpca_certificate_authority_permanent_deletion_time_in_days

  dynamic "certificate_authority_configuration" {
    iterator = certificate_authority_configuration
    for_each = length(keys(var.acmpca_certificate_authority_certificate_authority_configuration)) > 0 ? [var.acmpca_certificate_authority_certificate_authority_configuration] : []

    content {
      key_algorithm     = lookup(certificate_authority_configuration.value, "key_algorithm", null)
      signing_algorithm = lookup(certificate_authority_configuration.value, "signing_algorithm", null)

      dynamic "subject" {
        iterator = subject
        for_each = length(keys(lookup(certificate_authority_configuration.value, "subject", {}))) > 0 ? [lookup(certificate_authority_configuration.value, "subject", {})] : []

        content {
          common_name                  = lookup(subject.value, "common_name", null)
          country                      = lookup(subject.value, "country", null)
          distinguished_name_qualifier = lookup(subject.value, "distinguished_name_qualifier", null)
          generation_qualifier         = lookup(subject.value, "generation_qualifier", null)
          given_name                   = lookup(subject.value, "given_name", null)
          initials                     = lookup(subject.value, "initials", null)
          locality                     = lookup(subject.value, "locality", null)
          organization                 = lookup(subject.value, "organization", null)
          organizational_unit          = lookup(subject.value, "organizational_unit", null)
          pseudonym                    = lookup(subject.value, "pseudonym", null)
          state                        = lookup(subject.value, "state", null)
          surname                      = lookup(subject.value, "surname", null)
          title                        = lookup(subject.value, "title", null)
        }
      }
    }
  }

  dynamic "revocation_configuration" {
    iterator = revocation_configuration
    for_each = length(keys(var.acmpca_certificate_authority_revocation_configuration)) > 0 ? [var.acmpca_certificate_authority_revocation_configuration] : []

    content {
      dynamic "crl_configuration" {
        iterator = crl_configuration
        for_each = length(keys(lookup(revocation_configuration.value, "crl_configuration", {}))) > 0 ? [lookup(revocation_configuration.value, "crl_configuration", {})] : []

        content {
          expiration_in_days = lookup(crl_configuration.value, "expiration_in_days", null)

          custom_cname   = lookup(crl_configuration.value, "custom_cname", null)
          enabled        = lookup(crl_configuration.value, "enabled", null)
          s3_bucket_name = lookup(crl_configuration.value, "s3_bucket_name", null)
        }
      }
    }
  }

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.acmpca_certificate_authority_timeouts)) > 0 ? [var.acmpca_certificate_authority_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
    }
  }

  tags = merge(
    {
      Name = var.acmpca_certificate_authority_name != "" ? var.acmpca_certificate_authority_name : "${lower(var.name)}-acmpca-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: acmpca_certificate_authority_certificate.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (certificate authority certificate)
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/acmpca_certificate_authority_certificate

// File: acmpca_permission.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (permission)
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/acmpca_permission

// File: acmpca_policy.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (policy)
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/acmpca_policy

// File: outputs.tf
#---------------------------------------------------
# acm certificate
#---------------------------------------------------
output "aws_acm_certificate_id" {
  description = "The ARN of the certificate"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.id,
    aws_acm_certificate.acm_certificate_private_ca.*.id,
    aws_acm_certificate.acm_certificate_exist.*.id,
    [""]),
  0)
}

output "aws_acm_certificate_arn" {
  description = "The ARN of the certificate"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.arn,
    aws_acm_certificate.acm_certificate_private_ca.*.arn,
    aws_acm_certificate.acm_certificate_exist.*.arn,
    [""]),
  0)
}

output "aws_acm_certificate_domain_name" {
  description = "The domain name for which the certificate is issued"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.domain_name,
    aws_acm_certificate.acm_certificate_private_ca.*.domain_name,
    aws_acm_certificate.acm_certificate_exist.*.domain_name,
    [""]),
  0)
}

output "aws_acm_certificate_domain_validation_options" {
  description = "A list of attributes to feed into other resources to complete certificate validation. Can have more than one element, e.g. if SANs are defined. Only set if DNS-validation was used"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.domain_validation_options,
    aws_acm_certificate.acm_certificate_private_ca.*.domain_validation_options,
    aws_acm_certificate.acm_certificate_exist.*.domain_validation_options,
    [""]),
  0)
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate validation
#---------------------------------------------------
output "acm_certificate_validation_id" {
  description = "The time at which the certificate was issued"
  value       = element(concat(aws_acm_certificate_validation.acm_certificate_validation.*.id, [""]), 0)
}

#---------------------------------------------------
# acmpca
#---------------------------------------------------
output "acmpca_certificate_authority_id" {
  description = "Amazon Resource Name (ARN) of the certificate authority."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.id, [""]), 0)
}

output "acmpca_certificate_authority_arn" {
  description = "Amazon Resource Name (ARN) of the certificate authority."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.arn, [""]), 0)
}

output "acmpca_certificate_authority_certificate" {
  description = "Base64-encoded certificate authority (CA) certificate. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.certificate, [""]), 0)
}

output "acmpca_certificate_authority_certificate_chain" {
  description = "Base64-encoded certificate chain that includes any intermediate certificates and chains up to root on-premises certificate that you used to sign your private CA certificate. The chain does not include your private CA certificate. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.certificate_chain, [""]), 0)
}

output "acmpca_certificate_authority_certificate_signing_request" {
  description = "The base64 PEM-encoded certificate signing request (CSR) for your private CA certificate."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.certificate_signing_request, [""]), 0)
}

output "acmpca_certificate_authority_not_after" {
  description = "Date and time after which the certificate authority is not valid. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.not_after, [""]), 0)
}

output "acmpca_certificate_authority_not_before" {
  description = "Date and time before which the certificate authority is not valid. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.not_before, [""]), 0)
}

output "acmpca_certificate_authority_serial" {
  description = "Serial number of the certificate authority. Only available after the certificate authority certificate has been imported."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.serial, [""]), 0)
}

output "acmpca_certificate_authority_status" {
  description = "Status of the certificate authority."
  value       = element(concat(aws_acmpca_certificate_authority.acmpca_certificate_authority.*.status, [""]), 0)
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "Add additional tags"
  default     = {}
}

#-----------------------------------------------------------
# ACM
#-----------------------------------------------------------
variable "enable_acm_certificate" {
  description = "Enable acm certificate usage"
  default     = false
}

variable "acm_certificate_domain_name" {
  description = "(Required) A domain name for which the certificate should be issued"
  default     = ""
}

variable "acm_certificate_validation_method" {
  description = "(Required) Which method to use for validation. DNS or EMAIL are valid, NONE can be used for certificates that were imported into ACM and then into Terraform."
  default     = "DNS"
}

variable "acm_certificate_subject_alternative_names" {
  description = "(Optional) A list of domains that should be SANs in the issued certificate"
  default     = []
}

variable "acm_certificate_options" {
  description = "(Optional) Configuration block used to set certificate options."
  default     = []
}

variable "enable_import_existing_certificate" {
  description = "Enable import existing certificate usage"
  default     = false
}

variable "acm_certificate_private_key" {
  description = "(Required) The certificate's PEM-formatted private key"
  default     = ""
}

variable "acm_certificate_certificate_body" {
  description = "(Required) The certificate's PEM-formatted public key"
  default     = ""
}

variable "acm_certificate_certificate_chain" {
  description = "(Optional) The certificate's PEM-formatted chain"
  default     = null
}

variable "enable_acm_certificate_private_ca" {
  description = "Enable acm certificate private CA usage"
  default     = false
}

variable "acm_certificate_certificate_authority_arn" {
  description = "ARN of an ACMPCA"
  default     = null
}

#-----------------------------------------------------------
# acm_certificate_validation
#-----------------------------------------------------------
variable "enable_acm_certificate_validation" {
  description = "Enable to use acm certificate validation"
  default     = false
}

variable "acm_certificate_validation_certificate_arn" {
  description = "(Required) The ARN of the certificate that is being validated."
  default     = ""
}

variable "acm_certificate_validation_record_fqdns" {
  description = "(Optional) List of FQDNs that implement the validation. Only valid for DNS validation method ACM certificates. If this is set, the resource can implement additional sanity checks and has an explicit dependency on the resource that is implementing the validation"
  default     = null
}

variable "acm_certificate_validation_timeouts" {
  description = "Set timeouts for acm certificate validation"
  default     = {}
}

#-----------------------------------------------------------
# acmpca_certificate_authority
#-----------------------------------------------------------
variable "enable_acmpca_certificate_authority" {
  description = "Enable to use acmpca certificate authority"
  default     = false
}

variable "acmpca_certificate_authority_name" {
  description = "Set cert name for acmpca"
  default     = ""
}

variable "acmpca_certificate_authority_enabled" {
  description = "(Optional) Whether the certificate authority is enabled or disabled. Defaults to true."
  default     = true
}

variable "acmpca_certificate_authority_certificate_authority_configuration" {
  description = "(Required) Nested argument containing algorithms and certificate subject information."
  default     = {}
}

variable "acmpca_certificate_authority_permanent_deletion_time_in_days" {
  description = "(Optional) The number of days to make a CA restorable after it has been deleted, must be between 7 to 30 days, with default to 30 days."
  default     = null
}

variable "acmpca_certificate_authority_revocation_configuration" {
  description = "(Optional) Nested argument containing revocation configuration."
  default     = {}
}

variable "acmpca_certificate_authority_timeouts" {
  description = "Set timeouts for acmpca"
  default     = {}
}

// File: iam-foundation.tf
# Config 

terraform {
  required_version = ">=0.12.0"
  required_providers {
    aws = ">= 2.0"
  }
}

provider "aws" {
  region = var.region
}

# Variables

variable "name" {
  description = "Name for prefixes (including tailing dash)"
  type        = string
  default     = "awscademo-"
}
variable "region" {
  description = "Region for AWS ressources"
  type        = string
  default     = "us-east-1"
}

variable "tags-to-value" {
  type = map(string)
  default = {
    contact     = "odeyinka2001@yahoo.com"
    ttl         = "infinity"
    deployed-by = "terraform"
    date-deployed = "02-04-2023"
  }
  description = "Map of mandatory tags"
}


# IAM

## Default Group

resource "aws_iam_group" "demo-user-group" {
  name = format("%sdemo-users", var.name)
}

resource "aws_iam_policy" "self-management-policy" {
  name_prefix = substr(format("%suser-self-management-policy", var.name), 0, 31)
  description = format(
    "Policy for user self management of pwd, mfa device for %s",
    var.name,
  )
  ### Remark: During copy paste the policy json from AWS policy generator
  ### one has to escape the HCL reserved "${" by a second $ to indicate the use of AWS variables
  ### Better way would be to use fucntions file() and templatefile with external stored policy json files
  policy = <<EOP
{
    "Statement": [
      {
        "Action": [
          "iam:ChangePassword",
          "iam:*LoginProfile",
          "iam:*AccessKey*",
          "iam:*SSHPublicKey*",
          "iam:ListUserPolicies",
          "iam:ListAttachedUserPolicies",
          "iam:ListGroupsForUser"
        ],
        "Effect": "Allow",
        "Resource": "arn:aws:iam:::user/$${aws:username}",
        "Sid": "AllowCredentialManagement"
      },
      {
        "Action": [
          "iam:ListAccount*",
          "iam:GetAccountSummary",
          "iam:GetAccountPasswordPolicy",
          "iam:ListUsers"
        ],
        "Effect": "Allow",
        "Resource": "*",
        "Sid": "AllowConsoleUsage"
      },
      {
        "Action": [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice"
        ],
        "Effect": "Allow",
        "Resource": [
          "arn:aws:iam:::mfa/$${aws:username}",
          "arn:aws:iam:::user/$${aws:username}"
        ],
        "Sid": "AllowMfaCreateEnableResync"
      },
      {
        "Action": [
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices"
        ],
        "Effect": "Allow",
        "Resource": "*",
        "Sid": "AllowMfaFromConsole"
      },
      {
        "Action": [
          "iam:ListAccountAliases",
          "iam:ListUsers",
          "iam:ListVirtualMFADevices",
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary"
        ],
        "Effect": "Allow",
        "Resource": "*",
        "Sid": "AllowAllUsersToListAccounts"
      },
      {
        "Action": [
          "iam:ChangePassword",
          "iam:CreateAccessKey",
          "iam:CreateLoginProfile",
          "iam:DeleteAccessKey",
          "iam:DeleteLoginProfile",
          "iam:GetLoginProfile",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey",
          "iam:UpdateLoginProfile",
          "iam:ListSigningCertificates",
          "iam:DeleteSigningCertificate",
          "iam:UpdateSigningCertificate",
          "iam:UploadSigningCertificate",
          "iam:ListSSHPublicKeys",
          "iam:GetSSHPublicKey",
          "iam:DeleteSSHPublicKey",
          "iam:UpdateSSHPublicKey",
          "iam:UploadSSHPublicKey"
        ],
        "Effect": "Allow",
        "Resource": "arn:aws:iam::*:user/$${aws:username}",
        "Sid": "AllowIndividualUserToSeeAndManageOnlyTheirOwnAccountInformation"
      },
      {
        "Action": [
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ],
        "Effect": "Allow",
        "Resource": [
          "arn:aws:iam::*:mfa/$${aws:username}",
          "arn:aws:iam::*:user/$${aws:username}"
        ],
        "Sid": "AllowIndividualUserToViewAndManageTheirOwnMFA"
      },
      {
        "Action": [
          "iam:DeactivateMFADevice"
        ],
        "Condition": {
          "Bool": {
            "aws:MultiFactorAuthPresent": "true"
          }
        },
        "Effect": "Allow",
        "Resource": [
          "arn:aws:iam::*:mfa/$${aws:username}",
          "arn:aws:iam::*:user/$${aws:username}"
        ],
        "Sid": "AllowIndividualUserToDeactivateOnlyTheirOwnMFAOnlyWhenUsingMFA"
      }
    ],
    "Version": "2012-10-17"
  }

EOP
}

resource "aws_iam_group_policy_attachment" "self-management-attach" {
  group      = aws_iam_group.demo-user-group.name
  policy_arn = aws_iam_policy.self-management-policy.arn
  depends_on = [
    aws_iam_group.demo-user-group,
    aws_iam_policy.self-management-policy,
  ]
}

## Read only Group

resource "aws_iam_group" "readonly-user-group" {
  name = format("%sreadonly-users", var.name)
}

data "aws_iam_policy" "readonly-access-managed-policy" {
  arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "readonly-attach" {
  group      = aws_iam_group.readonly-user-group.name
  policy_arn = data.aws_iam_policy.readonly-access-managed-policy.arn
  depends_on = [
    aws_iam_group.readonly-user-group,
    data.aws_iam_policy.readonly-access-managed-policy,
  ]
}

## Admin group
resource "aws_iam_group" "mfa-superadmin-group" {
  name = format("%smfa-superadmins", var.name)
}

resource "aws_iam_role" "admin-role" {
  name_prefix          = substr(format("%smfa-superadmins-role", var.name), 0, 31)
  assume_role_policy   = data.aws_iam_policy_document.admin-assume-role-document.json
  max_session_duration = 43200 # 43200 seconds is the supported maximum, i.e. 12 hours
}

data "aws_iam_policy_document" "admin-policy-document" {
  statement {
    actions = [
      "*",
    ]
    effect = "Allow"
    resources = [
      "*",
    ]
    condition {
        test     = "BoolIfExists"
        variable = "aws:MultiFactorAuthPresent"
        values = [
        "true"
        ]      
      } 
  }
}

resource "aws_iam_policy" "admin-policy" {
  name_prefix = substr(format("%sadmin-access-policy", var.name), 0, 31)
  description = format("Permits full admin access for %s", var.name)
  path        = "/"
  policy      = data.aws_iam_policy_document.admin-policy-document.json
}

resource "aws_iam_role_policy_attachment" "admin-role-attach" {
  role       = aws_iam_role.admin-role.name
  policy_arn = aws_iam_policy.admin-policy.arn
  depends_on = [
    aws_iam_role.admin-role,
    aws_iam_policy.admin-policy,
  ]
}

resource "aws_iam_policy" "assume-role-mfa-policy" {
  depends_on  = [aws_iam_group.mfa-superadmin-group]
  name_prefix = substr(format("%sassume-admin-role-with-mfa-policy", var.name), 0, 31)
  path        = "/"
  description = format("Assume admin role with MFA only policy for %s", var.name)

  policy = <<EOP
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Action": "sts:AssumeRole",
            "Resource": "${aws_iam_role.admin-role.arn}",
            "Condition": {
                "BoolIfExists": {
                    "aws:MultiFactorAuthPresent": "true"
                }
            }
        }
    ]
}
EOP

}

resource "aws_iam_group_policy_attachment" "admin-assume-role-mfa-attach" {
  group      = aws_iam_group.mfa-superadmin-group.name
  policy_arn = aws_iam_policy.assume-role-mfa-policy.arn
  depends_on = [
    aws_iam_group.mfa-superadmin-group,
    aws_iam_policy.assume-role-mfa-policy,
  ]
}

data "aws_caller_identity" "current" {
}

data "aws_iam_policy_document" "admin-assume-role-document" {
  statement {
    actions = [
      "sts:AssumeRole",
    ]
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}



# Outputs

output "mfa-superadmin-group" {
  description = "The name of the IAM group for admins"
  value       = "${aws_iam_group.mfa-superadmin-group.id}"
}

output "read-only-group" {
  description = "The name of the IAM group for read only access permissions"
  value       = "${aws_iam_group.readonly-user-group.id}"
}

output "default-group" {
  description = "The name of the IAM group for evryone"
  value       = "${aws_iam_group.demo-user-group.id}"
}

// File: efs_access_point.tf
#---------------------------------------------------
# AWS EFS access point
#---------------------------------------------------
resource "aws_efs_access_point" "efs_access_point" {
  count = var.enable_efs_access_point ? 1 : 0

  file_system_id = var.efs_access_point_file_system_id != "" ? var.efs_access_point_file_system_id : (var.enable_efs_file_system ? element(aws_efs_file_system.efs_file_system.*.id, 0) : null)

  dynamic "posix_user" {
    iterator = posix_user
    for_each = var.efs_access_point_posix_user

    content {
      gid = lookup(posix_user.value, "gid", null)
      uid = lookup(posix_user.value, "uid", null)

      secondary_gids = lookup(posix_user.value, "secondary_gids", null)
    }
  }

  dynamic "root_directory" {
    iterator = root_directory
    for_each = var.efs_access_point_root_directory

    content {
      path = lookup(root_directory.value, "path", null)

      dynamic "creation_info" {
        iterator = creation_info
        for_each = length(keys(lookup(root_directory.value, "creation_info", {}))) > 0 ? [lookup(root_directory.value, "creation_info", {})] : []

        content {
          owner_gid   = lookup(creation_info.value, "owner_gid", null)
          owner_uid   = lookup(creation_info.value, "owner_uid", null)
          permissions = lookup(creation_info.value, "permissions", null)
        }
      }

    }
  }

  tags = merge(
    {
      Name = var.efs_access_point_name != "" ? var.efs_access_point_name : "${lower(var.name)}-efs-access-point-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_efs_file_system.efs_file_system
  ]
}

// File: efs_file_system.tf
#---------------------------------------------------
# AWS EFS file system
#---------------------------------------------------
resource "aws_efs_file_system" "efs_file_system" {
  count = var.enable_efs_file_system ? 1 : 0

  creation_token   = var.efs_file_system_creation_token
  encrypted        = var.efs_file_system_encrypted
  kms_key_id       = var.efs_file_system_kms_key_id
  performance_mode = var.efs_file_system_performance_mode

  provisioned_throughput_in_mibps = var.efs_file_system_provisioned_throughput_in_mibps
  throughput_mode                 = var.efs_file_system_throughput_mode

  dynamic "lifecycle_policy" {
    iterator = lifecycle_policy
    for_each = var.efs_file_system_lifecycle_policy

    content {
      transition_to_ia = lookup(lifecycle_policy.value, "transition_to_ia", null)
    }
  }

  tags = merge(
    {
      Name = var.efs_file_system_name != "" ? var.efs_file_system_name : "${lower(var.name)}-efs-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: efs_file_system_policy.tf
#---------------------------------------------------
# AWS EFS file system policy
#---------------------------------------------------
resource "aws_efs_file_system_policy" "efs_file_system_policy" {
  count = var.enable_efs_file_system_policy ? 1 : 0

  file_system_id = var.efs_file_system_policy_file_system_id != "" ? var.efs_file_system_policy_file_system_id : (var.enable_efs_file_system ? element(aws_efs_file_system.efs_file_system.*.id, 0) : null)

  policy = var.efs_file_system_policy_policy

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_efs_file_system.efs_file_system
  ]
}

// File: efs_mount_target.tf
#---------------------------------------------------
# AWS EFS mount target
#---------------------------------------------------
resource "aws_efs_mount_target" "efs_mount_target" {
  count = var.enable_efs_mount_target && length(var.efs_mount_target_subnet_ids) > 0 ? length(var.efs_mount_target_subnet_ids) : 0

  file_system_id  = var.efs_mount_target_file_system_id != "" ? var.efs_mount_target_file_system_id : element(concat(aws_efs_file_system.efs_file_system.*.id, [""]), 0)
  subnet_id       = var.efs_mount_target_subnet_ids[count.index]
  ip_address      = var.efs_mount_target_ip_address
  security_groups = var.efs_mount_target_security_groups

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_efs_file_system.efs_file_system
  ]
}

// File: outputs.tf
#---------------------------------------------------
# AWS EFS file system
#---------------------------------------------------
output "efs_file_system_id" {
  description = "The ID that identifies the file system (e.g. fs-ccfc0d65)."
  value       = element(concat(aws_efs_file_system.efs_file_system.*.id, [""]), 0)
}

output "efs_file_system_arn" {
  description = "Amazon Resource Name of the file system."
  value       = element(concat(aws_efs_file_system.efs_file_system.*.arn, [""]), 0)
}

output "efs_file_system_kms_key_id" {
  description = ""
  value       = element(concat(aws_efs_file_system.efs_file_system.*.kms_key_id, [""]), 0)
}

output "efs_file_system_dns_name" {
  description = "The DNS name for the filesystem per documented convention."
  value       = element(concat(aws_efs_file_system.efs_file_system.*.dns_name, [""]), 0)
}

#---------------------------------------------------
# AWS EFS mount target
#---------------------------------------------------
output "efs_mount_target_id" {
  description = "The ID of the mount target."
  value       = element(concat(aws_efs_mount_target.efs_mount_target.*.id, [""]), 0)
}

output "efs_mount_target_dns_name" {
  description = "The DNS name for the EFS file system."
  value       = element(concat(aws_efs_mount_target.efs_mount_target.*.dns_name, [""]), 0)
}

output "efs_mount_target_mount_target_dns_name" {
  description = "The DNS name for the given subnet/AZ per documented convention."
  value       = element(concat(aws_efs_mount_target.efs_mount_target.*.mount_target_dns_name, [""]), 0)
}

output "efs_mount_target_file_system_arn" {
  description = "Amazon Resource Name of the file system."
  value       = element(concat(aws_efs_mount_target.efs_mount_target.*.file_system_arn, [""]), 0)
}

output "efs_mount_target_network_interface_id" {
  description = "The ID of the network interface that Amazon EFS created when it created the mount target."
  value       = element(concat(aws_efs_mount_target.efs_mount_target.*.network_interface_id, [""]), 0)
}

output "efs_mount_target_availability_zone_name" {
  description = "The name of the Availability Zone (AZ) that the mount target resides in."
  value       = element(concat(aws_efs_mount_target.efs_mount_target.*.availability_zone_name, [""]), 0)
}

output "efs_mount_target_availability_zone_id" {
  description = "The unique and consistent identifier of the Availability Zone (AZ) that the mount target resides in."
  value       = element(concat(aws_efs_mount_target.efs_mount_target.*.availability_zone_id, [""]), 0)
}

output "efs_mount_target_owner_id" {
  description = "AWS account ID that owns the resource."
  value       = element(concat(aws_efs_mount_target.efs_mount_target.*.owner_id, [""]), 0)
}

#---------------------------------------------------
# AWS EFS file system policy
#---------------------------------------------------
output "efs_file_system_policy_id" {
  description = "The ID that identifies the file system (e.g. fs-ccfc0d65)."
  value       = element(concat(aws_efs_file_system_policy.efs_file_system_policy.*.id, [""]), 0)
}

#---------------------------------------------------
# AWS EFS access point
#---------------------------------------------------
output "efs_access_point_id" {
  description = "The ID of the access point."
  value       = element(concat(aws_efs_access_point.efs_access_point.*.id, [""]), 0)
}

output "efs_access_point_arn" {
  description = "Amazon Resource Name of the access point."
  value       = element(concat(aws_efs_access_point.efs_access_point.*.arn, [""]), 0)
}

output "efs_access_point_file_system_arn" {
  description = "Amazon Resource Name of the file system."
  value       = element(concat(aws_efs_access_point.efs_access_point.*.file_system_arn, [""]), 0)
}

