// File: main.tf
data "aws_ami" "latest_amazon_linux" {
  owners      = ["amazon"]
  most_recent = true
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_instance" "web" {
  ami                    = data.aws_ami.latest_amazon_linux.id
  instance_type          = var.server_size
  vpc_security_group_ids = [aws_security_group.web.id]
  user_data              = <<EOF
#!/bin/bash
yum -y update
yum -y install httpd
myip=`curl http://169.254.169.254/latest/meta-data/local-ipv4`
echo "<h2>${var.server_name}-WebServer with IP: $myip</h2><br>Build by Terraform!"  >  /var/www/html/index.html
sudo service httpd start
chkconfig httpd on
EOF

  tags = {
    Name  = "${var.server_name}-WebServer"
    Owner = "Denis Astahov"
  }
}

resource "aws_default_vpc" "default" {} # This need to be added since AWS Provider v4.29+ to get VPC id

resource "aws_security_group" "web" {
  name_prefix = "${var.server_name}-WebServer-SG"
  vpc_id      = aws_default_vpc.default.id # This need to be added since AWS Provider v4.29+ to set VPC id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name  = "${var.server_name}-WebServer SecurityGroup"
    Owner = "Denis Astahov"
  }
}

resource "aws_eip" "web" {
 domain    = "vpc" # Need to add in new AWS Provider version
  instance = aws_instance.web.id
  tags = {
    Name  = "${var.server_name}-WebServer-IP"
    Owner = "Denis Astahov"
  }
}

// File: outputs.tf
output "web_public_ip" {
  value = aws_eip.web.public_ip
}

// File: variables.tf
variable "server_name" {
  description = "Name for WebServer"
  type        = string
  default     = "demo"
}


variable "server_size" {
  description = "Server Size for WebServer"
  type        = string
  default     = "t3.micro"
}

// File: main.tf
###############
# VPC Section #
###############

# VPCs

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  awsAz1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  awsAz2 = var.awsAz2 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1]
}
resource "aws_vpc" "vpcMain" {
  cidr_block = var.vpcMainCidr
  tags = {
    Name  = "${var.projectPrefix}-vpcMain-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Subnets

resource "aws_subnet" "vpcMainSubPubA" {
  vpc_id                  = aws_vpc.vpcMain.id
  cidr_block              = var.vpcMainSubPubACidr
  map_public_ip_on_launch = var.map_public_ip_on_launch
  availability_zone       = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPubA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPubB" {
  vpc_id                  = aws_vpc.vpcMain.id
  cidr_block              = var.vpcMainSubPubBCidr
  map_public_ip_on_launch = var.map_public_ip_on_launch
  availability_zone       = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPubB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubMgmtA" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubMgmtA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubMgmtB" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubMgmtB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPrivA" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPrivA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPrivB" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPrivB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Internet Gateway

resource "aws_internet_gateway" "vpcMainIgw" {
  vpc_id = aws_vpc.vpcMain.id

  tags = {
    Name  = "${var.projectPrefix}-vpcMainIgw-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Main Route Tables Associations

resource "aws_main_route_table_association" "mainRtbAssoVpcMain" {
  vpc_id         = aws_vpc.vpcMain.id
  route_table_id = aws_route_table.vpcMainRtb.id
}

# Route Tables

resource "aws_route_table" "vpcMainRtb" {
  vpc_id = aws_vpc.vpcMain.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.vpcMainIgw.id
  }

  tags = {
    Name  = "${var.projectPrefix}-vpcMainRtb-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

// File: outputs.tf
locals {
  vpcs = {
    "main" = aws_vpc.vpcMain.id
  }
  subnetsAz1 = {
    "public"  = aws_subnet.vpcMainSubPubA.id
    "private" = aws_subnet.vpcMainSubMgmtA.id
    "mgmt"    = aws_subnet.vpcMainSubPrivA.id
  }
  subnetsAz2 = {
    "public"  = aws_subnet.vpcMainSubPubB.id
    "private" = aws_subnet.vpcMainSubMgmtB.id
    "mgmt"    = aws_subnet.vpcMainSubPrivB.id
  }
}

output "vpcs" {
  value = local.vpcs
}

output "subnetsAz1" {
  value = local.subnetsAz1
}

output "subnetsAz2" {
  value = local.subnetsAz2
}

output "vpcMainIgw" {
  value = aws_internet_gateway.vpcMainIgw.id
}
output "vpcMainRtb" {
  value = aws_route_table.vpcMainRtb.id
}

// File: variables.tf
variable "projectPrefix" {
  description = "projectPrefix name to use for tags"
  default     = "f5-dcec"
}
variable "resourceOwner" {
  description = "owner of the deployment, for tagging purposes"
  default     = "f5-user"
}
variable "buildSuffix" {
  description = "random string for tagging purposes"
  default     = "YY"
}
variable "awsAz1" {
  default = null
}
variable "awsAz2" {
  default = null
}
variable "awsRegion" {
  default = "us-east-1"
}
variable "map_public_ip_on_launch" {
  description = "assigns public ip's to instances in the public subnet by default"
  default     = false
}
variable "vpcMainCidr" {
  default = "10.1.0.0/16"
}
variable "vpcMainSubPubACidr" {
  default = "10.1.10.0/24"
}
variable "vpcMainSubPubBCidr" {
  default = "10.1.110.0/24"
}
variable "vpcMainSubMgmtACidr" {
  default = "10.1.1.0/24"
}
variable "vpcMainSubMgmtBCidr" {
  default = "10.1.101.0/24"
}
variable "vpcMainSubPrivACidr" {
  default = "10.1.20.0/24"
}
variable "vpcMainSubPrivBCidr" {
  default = "10.1.120.0/24"
}

// File: main.tf
provider "aws" {
  region = "us-east-1"
}
terraform {
  required_version = ">= 1.0.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

resource "aws_s3_bucket" "terraform_state" {

  bucket = var.bucket_name

  // This is only here so we can destroy the bucket as part of automated tests. You should not copy this for production
  // usage
  force_destroy = true

}

# Enable versioning so you can see the full revision history of your
# state files
resource "aws_s3_bucket_versioning" "enabled" {
  bucket = aws_s3_bucket.terraform_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Enable server-side encryption by default
resource "aws_s3_bucket_server_side_encryption_configuration" "default" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Explicitly block all public access to the S3 bucket
resource "aws_s3_bucket_public_access_block" "public_access" {
  bucket                  = aws_s3_bucket.terraform_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "terraform_locks" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}

// File: outputs.tf
output "s3_bucket_arn" {
  value       = aws_s3_bucket.terraform_state.arn
  description = "The ARN of the S3 bucket"
}

output "dynamodb_table_name" {
  value       = aws_dynamodb_table.terraform_locks.name
  description = "The name of the DynamoDB table"
}

// File: variables.tf
variable "bucket_name" {
  description = "The name of the S3 bucket. Must be globally unique."
  type        = string
  default = "tungleo-terraform-state-s3"
}

variable "table_name" {
  description = "The name of the DynamoDB table. Must be unique in this AWS account."
  type        = string
  default = "terraform-up-and-running-locks"
}

// File: Bronze_Backup.tf
# ################################################################
# . Author : Ankit Upadhyay
# . Follow me on github for more aws maintainance resources  http://github.com/ankitosh
# 
# ################################################################

resource "aws_backup_vault" "BackupVault_Bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "BackupPlan_Bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    schedule          = "cron(0 0 ? * FRI *)"
    target_vault_name = aws_backup_vault.BackupVault_Bronze.id
    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_selection" "BackupResourceSelection_Bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.BackupPlan_Bronze.id
  iam_role_arn = aws_iam_role.IamRoleForAwsBackup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

// File: Gold_Backup.tf
# ################################################################
# . Author : Ankit Upadhyay
# . Follow me on github for more aws maintainance resources  http://github.com/ankitosh
# 
# ################################################################

resource "aws_backup_vault" "BackupVault_gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "BackupPlan_gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    schedule          = "cron(0 0 * * ? *)"
    target_vault_name = aws_backup_vault.BackupVault_gold.id
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    schedule          = "cron(0 0 1 1/1 ? *)"
    target_vault_name = aws_backup_vault.BackupVault_gold.id
    lifecycle {
      delete_after = 365
    }
  }
  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    schedule          = "cron(0 0 31 12 ? *)"
    target_vault_name = aws_backup_vault.BackupVault_gold.id
    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_selection" "BackupResourceSelection_gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.BackupPlan_gold.id
  iam_role_arn = aws_iam_role.IamRoleForAwsBackup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

// File: Premium_Backup.tf
# ################################################################
# . Author : Ankit Upadhyay
# . Follow me on github for more aws maintainance resources  http://github.com/ankitosh
# 
# ################################################################

resource "aws_backup_vault" "BackupVault_premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_plan" "BackupPlan_premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    schedule          = "cron(0 0/4 ? * * *)"
    target_vault_name = aws_backup_vault.BackupVault_premium.id
    lifecycle {
      delete_after = 1
    }
  }
  rule {
    rule_name         = "Premium_Daily_Backup"
    schedule          = "cron(0 0 * * ? *)"
    target_vault_name = aws_backup_vault.BackupVault_premium.id
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Premium_Monthly"
    schedule          = "cron(0 0 1 1/1 ? *)"
    target_vault_name = aws_backup_vault.BackupVault_premium.id
    lifecycle {
      delete_after       = 365
      cold_storage_after = 15
    }
  }
  rule {
    rule_name         = "Premium_Yearly"
    schedule          = "cron(0 0 31 12 ? *)"
    target_vault_name = aws_backup_vault.BackupVault_premium.id
    lifecycle {
      delete_after       = 2555
      cold_storage_after = 15
    }
  }
}

resource "aws_backup_selection" "BackupResourceSelection_premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.BackupPlan_premium.id
  iam_role_arn = aws_iam_role.IamRoleForAwsBackup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}

// File: backup_role.tf
resource "aws_iam_role" "IamRoleForAwsBackup" {
  name               = "Bronze_Backup_Role"
  assume_role_policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": ["backup.amazonaws.com"]
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
POLICY
}

resource "aws_iam_role_policy_attachment" "IamRoleForAwsBackupManagedPolicyRoleAttachment0" {
  role       = aws_iam_role.IamRoleForAwsBackup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "IamRoleForAwsBackupManagedPolicyRoleAttachment1" {
  role       = aws_iam_role.IamRoleForAwsBackup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

