// File: pipelines.tf
resource "aws_codestarconnections_connection" "pipeline" {
  for_each = { for i in local.sources : "${i.pipeline_name}-${i.stage_name}-${i.name}" => i if contains(local.codestarconnection_providers, i.provider) }

  name          = each.key
  provider_type = each.value.provider
}

# CodePipeline resources configuration
resource "aws_codepipeline" "pipeline" {
  for_each = try({ for p in local.config : p.name => p }, {})

  name = each.value.name

  role_arn = length(try(each.value.iam_role, "")) > 0 ? each.value.iam_role : aws_iam_role.default_pipeline.arn

  artifact_store {
    location = aws_s3_bucket.artifact_store[each.value.name].id
    type     = "S3"
  }

  # === SOURCES ===

  stage {
    name = "Sources"

    # Codecommit source
    dynamic "action" {
      for_each = { for i in local.sources : "${i.pipeline_name}-${i.stage_name}-${i.name}" => i if i.provider == "CodeCommit" }

      content {
        name             = action.value.name
        category         = "Source"
        owner            = "AWS"
        provider         = action.value.provider
        output_artifacts = action.value.output_artifacts
        version          = action.value.version
        namespace        = action.value.namespace
        run_order        = action.value.run_order

        configuration = {
          RepositoryName       = action.value.repository
          BranchName           = action.value.branch
          PollForSourceChanges = action.value.poll
          OutputArtifactFormat = action.value.output_artifacts_format
        }
      }
    }

    dynamic "action" {
      for_each = { for i in local.sources : "${i.pipeline_name}-${i.stage_name}-${i.name}" => i if i.provider == "S3" }

      content {
        name             = action.value.name
        category         = "Source"
        owner            = action.value.owner
        provider         = action.value.provider
        output_artifacts = action.value.output_artifacts
        version          = action.value.version
        namespace        = action.value.namespace
        run_order        = action.value.run_order

        configuration = {
          S3Bucket             = action.value.bucket
          S3ObjectKey          = action.value.object_key
          PollForSourceChanges = action.value.poll
        }
      }
    }

    dynamic "action" {
      for_each = { for i in local.sources : "${i.pipeline_name}-${i.stage_name}-${i.name}" => i if i.provider == "ECR" }

      content {
        name             = action.value.name
        category         = "Source"
        owner            = "AWS"
        provider         = action.value.provider
        output_artifacts = action.value.output_artifacts
        version          = action.value.version
        namespace        = action.value.namespace
        run_order        = action.value.run_order

        configuration = {
          ImageTag       = action.value.image_tag
          RepositoryName = action.value.repository
        }
      }
    }

    dynamic "action" {
      for_each = { for i in local.sources : "${i.pipeline_name}-${i.stage_name}-${i.name}" => i if contains(local.codestarconnection_providers, i.provider) }

      content {
        name             = action.value.name
        category         = "Source"
        owner            = "AWS"
        provider         = "CodeStarSourceConnection"
        output_artifacts = action.value.output_artifacts
        version          = action.value.version
        namespace        = action.value.namespace
        run_order        = action.value.run_order

        configuration = {
          ConnectionArn        = aws_codestarconnections_connection.pipeline["${action.value.pipeline_name}-${action.value.stage_name}-${action.value.name}"].arn
          FullRepositoryId     = action.value.repository
          BranchName           = action.value.branch
          DetectChanges        = action.value.poll
          OutputArtifactFormat = action.value.output_artifacts_format
        }
      }
    }
  }

  dynamic "stage" {
    for_each = { for i, s in local.stages_config : "${s.order}-${s.pipeline_name}-${s.name}" => s if each.value.name == s.pipeline_name }

    content {
      name = stage.value.name
      dynamic "action" {

        for_each = { for a in local.actions_config : "${a.pipeline_name}-${a.name}" => a if each.value.name == a.pipeline_name && stage.value.name == a.stage_name && a.category == "Build" }

        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          version          = action.value.version
          run_order        = action.value.run_order

          configuration = {
            ProjectName   = module.codebuild_action["${action.value.pipeline_name}-${action.value.stage_name}-${action.value.name}"].codebuild_project_name[0]
            PrimarySource = action.value.input_artifacts[0]
            EnvironmentVariables = jsonencode([
              {
                name  = "SOURCE_BRANCH_NAME"
                value = "#{SourceVariables.BranchName}"
                type  = "PLAINTEXT"
              },
              {
                name  = "SOURCE_COMMIT_ID"
                value = "#{SourceVariables.CommitId}"
                type  = "PLAINTEXT"
              },
              {
                name  = "SOURCE_REPOSITORY_NAME"
                value = "#{SourceVariables.RepositoryName}"
                type  = "PLAINTEXT"
              },
              {
                name  = "PIPELINE_EXEC_ID"
                value = "#{codepipeline.PipelineExecutionId}"
                type  = "PLAINTEXT"
              },
            ])
          }
        }
      }

      dynamic "action" {

        for_each = { for a in local.actions_config : "${a.pipeline_name}-${a.name}" => a if each.value.name == a.pipeline_name && stage.value.name == a.stage_name && a.category == "Approval" }

        content {
          name     = action.value.name
          category = action.value.category
          owner    = action.value.owner
          provider = action.value.provider
          version  = action.value.version
        }
      }

      dynamic "action" {

        for_each = { for a in local.actions_config : "${a.pipeline_name}-${a.name}" => a if each.value.name == a.pipeline_name && stage.value.name == a.stage_name && a.provider == "Lambda" }

        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          version          = action.value.version
          run_order        = action.value.run_order

          configuration = {
            FunctionName   = module.lambda_action["${action.value.pipeline_name}-${action.value.stage_name}-${action.value.name}"].lambda_id[0]
            UserParameters = action.value.user_params
          }
        }
      }
    }
  }

  tags = local.common_tags

  depends_on = [
    module.codebuild_action,
    module.lambda_action,
  ]
}

// File: stores.tf
resource "aws_s3_bucket" "artifact_store" {
  for_each = try({ for i in local.shared_artifacts : i.pipeline_name => i }, {})

  bucket = each.value.name

  tags = local.common_tags
}

resource "aws_s3_bucket" "build_cache_store" {
  for_each = try({ for i in local.shared_cache : i.pipeline_name => i }, {})

  bucket = each.value.name

  tags = local.common_tags
}

// File: triggers.tf
# === TRIGGERS & their supporting resources ===
#
# These section contains configuration for triggers, which trigger pipeline
# execution based on the tracked events

data "aws_iam_policy_document" "event_assume" {
  statement {
    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

# Configure Cloudwatch event IAM role(s)
resource "aws_iam_role" "event_role" {
  for_each = try({ for p in local.config : p.name => p }, {})

  name               = "terrabits-${each.value.name}"
  assume_role_policy = data.aws_iam_policy_document.event_assume.json

  tags = local.common_tags
}

resource "aws_iam_role_policy" "event_policy" {
  for_each = try({ for p in local.config : p.name => p }, {})

  name   = "${each.value.name}-events"
  role   = aws_iam_role.event_role[each.value.name].id
  policy = <<EOF
{
  "Statement": [
    {
      "Action": [
        "codepipeline:StartPipelineExecution"
      ],
      "Effect": "Allow",
      "Resource": "${aws_codepipeline.pipeline[each.value.name].arn}"
    }
  ]
}
EOF
}

data "aws_codecommit_repository" "codecommit_trigger" {
  for_each = try({ for t in local.codecommit_triggers : t.repository => t }, {})

  repository_name = each.value.repository
}

# === (Codecommit) BRANCH triggers ===
#
# Codecommit branch update Eventbridge pipeline trigger

resource "aws_cloudwatch_event_rule" "branch_trigger" {
  for_each = try({ for t in local.codecommit_triggers : "${t.pipeline_name}-${t.type}" => t if t.type == "branch" }, {})

  name        = "${each.key}-trigger"
  description = "Capture CodeCommit merge to branch events for ${each.value.repository}"

  event_pattern = <<PATTERN
{
  "source": [
    "aws.codecommit"
  ],
  "detail-type": [
    "CodeCommit Repository State Change"
  ],
  "resources": [
    "${data.aws_codecommit_repository.codecommit_trigger[each.value.repository].arn}"
  ],
  "detail": {
    "referenceType": [
      "branch"
    ],
    "referenceName": [
      "${each.value.branch}"
    ]
  }
}
PATTERN
}

resource "aws_cloudwatch_event_target" "branch_trigger" {
  for_each = try({ for t in local.codecommit_triggers : "${t.pipeline_name}-${t.type}" => t if t.type == "branch" }, {})

  rule     = aws_cloudwatch_event_rule.branch_trigger["${each.value.pipeline_name}-${each.value.type}"].name
  role_arn = aws_iam_role.event_role[each.value.pipeline_name].arn
  arn      = aws_codepipeline.pipeline[each.value.pipeline_name].arn
}

# === (Codecommit) TAG triggers ===
#
# Codecommit tag update Eventbridge pipeline trigger

resource "aws_cloudwatch_event_rule" "tag_trigger" {
  for_each = try({ for t in local.codecommit_triggers : "${t.pipeline_name}-${t.type}" => t if t.type == "tag" }, {})

  name        = "${each.key}-trigger"
  description = "Capture CodeCommit merge to tag events for ${each.value.repository}"

  event_pattern = <<PATTERN
{
  "source": [
    "aws.codecommit"
  ],
  "detail-type": [
    "CodeCommit Repository State Change"
  ],
  "resources": [
    "${data.aws_codecommit_repository.codecommit_trigger[each.value.repository].arn}"
  ],
  "detail": {
    "referenceType": [
      "tag"
    ],
    "referenceName": [
      "${each.value.tag}"
    ]
  }
}
PATTERN
}

resource "aws_cloudwatch_event_target" "tag_trigger" {
  for_each = try({ for t in local.codecommit_triggers : "${t.pipeline_name}-${t.type}" => t if t.type == "tag" }, {})

  rule     = aws_cloudwatch_event_rule.tag_trigger["${each.value.pipeline_name}-${each.value.type}"].name
  role_arn = aws_iam_role.event_role[each.value.pipeline_name].arn
  arn      = aws_codepipeline.pipeline[each.value.pipeline_name].arn
}

#  === CRON triggers ===
#
# Cron-based Eventbridge pipeline trigger

resource "aws_cloudwatch_event_rule" "cron_trigger" {
  for_each = try({ for t in local.cron_triggers : "${t.pipeline_name}-${t.type}" => t }, {})

  name                = "${each.key}-trigger"
  description         = "Capture cron trigger events for ${each.value.pipeline_name} pipeline"
  schedule_expression = each.value.expression
}

resource "aws_cloudwatch_event_target" "cron_trigger" {
  for_each = try({ for t in local.cron_triggers : "${t.pipeline_name}-${t.type}" => t }, {})

  rule     = aws_cloudwatch_event_rule.cron_trigger["${each.value.pipeline_name}-${each.value.type}"].name
  role_arn = aws_iam_role.event_role[each.value.pipeline_name].arn
  arn      = aws_codepipeline.pipeline[each.value.pipeline_name].arn
}

#  === EVENTBRIDGE triggers ===
#
# Custom Eventbridge event pipeline trigger

resource "aws_cloudwatch_event_rule" "eventbridge_trigger" {
  for_each = try({ for t in local.eventbridge_triggers : "${t.pipeline_name}-${t.type}" => t }, {})

  name        = "${each.key}-trigger"
  description = "Capture Eventbridge custom event for ${each.value.pipeline_name} pipeline"

  event_pattern = each.value.event_pattern
}

resource "aws_cloudwatch_event_target" "eventbridge_trigger" {
  for_each = try({ for t in local.eventbridge_triggers : "${t.pipeline_name}-${t.type}" => t }, {})

  rule     = aws_cloudwatch_event_rule.eventbridge_trigger["${each.value.pipeline_name}-${each.value.type}"].name
  role_arn = aws_iam_role.event_role[each.value.pipeline_name].arn
  arn      = aws_codepipeline.pipeline[each.value.pipeline_name].arn
}

// File: variables.tf
variable "config" {
  type    = string
  default = "Path to the pipeline configuration file"
}

variable "shared_tags" {
  type        = map(any)
  description = "Additional user defiend resoirce tags"
  default     = {}
}

// File: main.tf
locals {
  aws_account_id = var.aws_account_id != "" ? var.aws_account_id : data.aws_caller_identity.current.account_id
  # clean URLs of https:// prefix
  urls = [
    for url in compact(distinct(concat(var.provider_urls, [var.provider_url]))) :
    replace(url, "https://", "")
  ]
  number_of_role_policy_arns = coalesce(var.number_of_role_policy_arns, length(var.role_policy_arns))
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

data "aws_iam_policy_document" "assume_role_with_oidc" {
  count = var.create_role ? 1 : 0

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role ? [1] : []

    content {
      sid     = "ExplicitSelfRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role${var.role_path}${var.role_name}"]
      }
    }
  }

  dynamic "statement" {
    for_each = local.urls

    content {
      effect  = "Allow"
      actions = ["sts:AssumeRoleWithWebIdentity"]

      principals {
        type = "Federated"

        identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.aws_account_id}:oidc-provider/${statement.value}"]
      }

      dynamic "condition" {
        for_each = length(var.oidc_fully_qualified_subjects) > 0 ? local.urls : []

        content {
          test     = "StringEquals"
          variable = "${statement.value}:sub"
          values   = var.oidc_fully_qualified_subjects
        }
      }

      dynamic "condition" {
        for_each = length(var.oidc_subjects_with_wildcards) > 0 ? local.urls : []

        content {
          test     = "StringLike"
          variable = "${statement.value}:sub"
          values   = var.oidc_subjects_with_wildcards
        }
      }

      dynamic "condition" {
        for_each = length(var.oidc_fully_qualified_audiences) > 0 ? local.urls : []

        content {
          test     = "StringLike"
          variable = "${statement.value}:aud"
          values   = var.oidc_fully_qualified_audiences
        }
      }
    }
  }
}

resource "aws_iam_role" "this" {
  count = var.create_role ? 1 : 0

  name                 = var.role_name
  name_prefix          = var.role_name_prefix
  description          = var.role_description
  path                 = var.role_path
  max_session_duration = var.max_session_duration

  force_detach_policies = var.force_detach_policies
  permissions_boundary  = var.role_permissions_boundary_arn

  assume_role_policy = join("", data.aws_iam_policy_document.assume_role_with_oidc.*.json)

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "custom" {
  count = var.create_role ? local.number_of_role_policy_arns : 0

  role       = join("", aws_iam_role.this.*.name)
  policy_arn = var.role_policy_arns[count.index]
}

// File: outputs.tf
output "iam_role_arn" {
  description = "ARN of IAM role"
  value       = try(aws_iam_role.this[0].arn, "")
}

output "iam_role_name" {
  description = "Name of IAM role"
  value       = try(aws_iam_role.this[0].name, "")
}

output "iam_role_path" {
  description = "Path of IAM role"
  value       = try(aws_iam_role.this[0].path, "")
}

output "iam_role_unique_id" {
  description = "Unique ID of IAM role"
  value       = try(aws_iam_role.this[0].unique_id, "")
}

// File: variables.tf
variable "create_role" {
  description = "Whether to create a role"
  type        = bool
  default     = false
}

variable "provider_url" {
  description = "URL of the OIDC Provider. Use provider_urls to specify several URLs."
  type        = string
  default     = ""
}

variable "provider_urls" {
  description = "List of URLs of the OIDC Providers"
  type        = list(string)
  default     = []
}

variable "aws_account_id" {
  description = "The AWS account ID where the OIDC provider lives, leave empty to use the account for the AWS provider"
  type        = string
  default     = ""
}

variable "tags" {
  description = "A map of tags to add to IAM role resources"
  type        = map(string)
  default     = {}
}

variable "role_name" {
  description = "IAM role name"
  type        = string
  default     = null
}

variable "role_name_prefix" {
  description = "IAM role name prefix"
  type        = string
  default     = null
}

variable "role_description" {
  description = "IAM Role description"
  type        = string
  default     = ""
}

variable "role_path" {
  description = "Path of IAM role"
  type        = string
  default     = "/"
}

variable "role_permissions_boundary_arn" {
  description = "Permissions boundary ARN to use for IAM role"
  type        = string
  default     = ""
}

variable "max_session_duration" {
  description = "Maximum CLI/API session duration in seconds between 3600 and 43200"
  type        = number
  default     = 3600
}

variable "role_policy_arns" {
  description = "List of ARNs of IAM policies to attach to IAM role"
  type        = list(string)
  default     = []
}

variable "number_of_role_policy_arns" {
  description = "Number of IAM policies to attach to IAM role"
  type        = number
  default     = null
}

variable "oidc_fully_qualified_subjects" {
  description = "The fully qualified OIDC subjects to be added to the role policy"
  type        = set(string)
  default     = []
}

variable "oidc_subjects_with_wildcards" {
  description = "The OIDC subject using wildcards to be added to the role policy"
  type        = set(string)
  default     = []
}

variable "oidc_fully_qualified_audiences" {
  description = "The audience to be added to the role policy. Set to sts.amazonaws.com for cross-account assumable role. Leave empty otherwise."
  type        = set(string)
  default     = []
}

variable "force_detach_policies" {
  description = "Whether policies should be detached from this role when destroying"
  type        = bool
  default     = false
}

variable "allow_self_assume_role" {
  description = "Determines whether to allow the role to be [assume itself](https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/)"
  type        = bool
  default     = false
}

// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

// File: data.tf
######################
## data sources
######################
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

// File: locals.tf
locals {
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id
  dns_suffix = data.aws_partition.current.dns_suffix

  policy = jsonencode({
    "Version" : "2012-10-17",
    "Statement" : [
      {
        "Sid" : "Allow KMS Permissions to Service",
        "Effect" : "Allow",
        "Principal" : {
          "Service" : "logs.${local.region}.${local.dns_suffix}"
        },
        "Action" : [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ],
        "Resource" : "*"
      },

      {
        "Sid" : "Enable IAM User Permissions",
        "Effect" : "Allow",
        "Principal" : {
          "AWS" : "arn:${local.partition}:iam::${local.account_id}:root"
        },
        "Action" : [
          "kms:*"
        ],
        "Resource" : "*",
      }
    ]
  })
}

// File: main.tf
#######################################################
## KMS Key data.aws_iam_policy_document.kms.json
#######################################################

resource "aws_kms_key" "sns" {
  count                   = var.create_kms_key ? 1 : 0
  description             = "KMS Key for SNStopic ${var.name}"
  policy                  = local.policy
  deletion_window_in_days = var.key_deletion_window
  enable_key_rotation     = var.enable_key_rotation
}

resource "aws_kms_alias" "sns" {
  count         = var.create_kms_key ? 1 : 0
  name          = "alias/sns/${trim(var.name, ".fifo")}"
  target_key_id = aws_kms_key.sns[0].key_id
}

##################
## sns topic
##################
resource "aws_sns_topic" "main" {
  name                                     = var.name
  name_prefix                              = var.name != null ? null : var.name_prefix
  display_name                             = var.display_name
  delivery_policy                          = var.delivery_policy
  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn
  http_success_feedback_role_arn           = var.http_success_feedback_role_arn
  http_success_feedback_sample_rate        = var.http_success_feedback_sample_rate
  http_failure_feedback_role_arn           = var.http_failure_feedback_role_arn
  kms_master_key_id                        = var.create_kms_key && var.kms_master_key_arn == null ? aws_kms_key.sns[0].arn : (var.create_kms_key == false && var.kms_master_key_arn != null ? var.kms_master_key_arn : "alias/aws/sns")
  fifo_topic                               = var.fifo_topic
  content_based_deduplication              = var.content_based_deduplication
  lambda_success_feedback_role_arn         = var.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate      = var.lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn         = var.lambda_failure_feedback_role_arn
  sqs_success_feedback_role_arn            = var.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate         = var.sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn            = var.sqs_failure_feedback_role_arn
  firehose_success_feedback_role_arn       = var.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate    = var.firehose_success_feedback_sample_rate
  firehose_failure_feedback_role_arn       = var.firehose_failure_feedback_role_arn
  tags                                     = var.tags
}

resource "aws_sns_topic_policy" "main" {
  count  = var.create_sns_topic_policy ? 1 : 0
  arn    = aws_sns_topic.main.arn
  policy = var.policy
}

#########################
## sns topic subscription
#########################
resource "aws_sns_topic_subscription" "main" {
  for_each                        = var.sns_topic_subscriptions
  topic_arn                       = aws_sns_topic.main.arn
  endpoint                        = lookup(each.value, "endpoint", null)
  protocol                        = lookup(each.value, "protocol", null)
  subscription_role_arn           = lookup(each.value, "subscription_role_arn", null)
  confirmation_timeout_in_minutes = lookup(each.value, "confirmation_timeout_in_minutes", null)
  delivery_policy                 = lookup(each.value, "delivery_policy", null)
  endpoint_auto_confirms          = lookup(each.value, "endpoint_auto_confirms", null)
  filter_policy                   = lookup(each.value, "filter_policy", null)
  raw_message_delivery            = lookup(each.value, "raw_message_delivery", null)
  redrive_policy                  = lookup(each.value, "redrive_policy", null)
}

// File: outputs.tf
#########################
## sns topic
#########################

output "id" {
  value       = aws_sns_topic.main.id
  description = "The ARN of the SNS topic"
}

output "arn" {
  value       = aws_sns_topic.main.arn
  description = "The ARN of the SNS topic, as a more obvious property (clone of id)"
}

output "owner" {
  value       = aws_sns_topic.main.owner
  description = "The AWS Account ID of the SNS topic owner"
}

output "tags_all" {
  value       = aws_sns_topic.main.tags_all
  description = "A map of tags assigned to the resource, including those inherited from the provider [`default_tags` configuration block](https://registry.terraform.io/docs/providers/aws/index#default_tags-configuration-block)."
}

#########################
## sns topic subscription
#########################

output "subscription_arn" {
  value = [
    for subscription in aws_sns_topic_subscription.main : subscription.arn
  ]
  description = "ARN of the subscription."
}

output "subscription_confirmation_was_authenticated" {
  value = [
    for subscription in aws_sns_topic_subscription.main : subscription.confirmation_was_authenticated
  ]
  description = "Whether the subscription confirmation request was authenticated."
}

output "subscription_id" {
  value = [
    for subscription in aws_sns_topic_subscription.main : subscription.id
  ]
  description = "ARN of the subscription."
}

output "subscription_owner_id" {
  value = [
    for subscription in aws_sns_topic_subscription.main : subscription.owner_id
  ]
  description = "AWS account ID of the subscription's owner."
}

output "subscription_pending_confirmation" {
  value = [
    for subscription in aws_sns_topic_subscription.main : subscription.pending_confirmation
  ]
  description = "Whether the subscription has not been confirmed."
}

