// File: main.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source = "hashicorp/random"
      version = "3.6.0"
    }
  }
}

resource "random_uuid" "random" {
}

provider "aws" {
  profile = "default"
  region = var.aws_region
}

resource "aws_s3_bucket" "s3_resource" {
  bucket = "${var.s3_bucket_name}-${lower(random_uuid.random.result)}"
  tags = {
    Stage = "dev"
    CreatedBy = "Jesus Plasencia"
  }
}

// File: variables.tf
variable "aws_region" {
  description = "AWS region to deploy the resources"
  type = string
  default = "us-east-1"
}

variable "s3_bucket_name" {
  description = "The name of the S3 Bucket"
  type = string
  default = "tp-s3-dev"
}

// File: s3-bucket.tf
resource "aws_s3_bucket" "artifactory_s3_bucket" {
  bucket = "ashrafk-artifactory-bucket"

  tags = {
    provisioned_by = "terraform"
  }
}

resource "aws_s3_bucket_ownership_controls" "artifactory_s3_ownership" {
  bucket = aws_s3_bucket.artifactory_s3_bucket.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "artifactory_s3_acl" {
  depends_on = [aws_s3_bucket_ownership_controls.artifactory_s3_ownership]
  bucket = aws_s3_bucket.artifactory_s3_bucket.id
  acl    = "private"
}

// File: s3-iam-role.tf
resource "aws_iam_role" "artifactory-s3-full-access" {
  name = "eks-pod-s3-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity",
        Effect = "Allow",
        Principal = {
          Federated = "<YOUR-EKS-OIDC>" // Replace with OIDC of your EKS
        },
        Condition = {
          StringEquals = {
            "<YOUR-EKS-OIDC>": [ // Replace with OIDC of your EKS
                "sts.amazonaws.com"
            ]
          }
        }
      }
    ]
  })

  tags = {
    provisioned_by = "terraform"
  }
}

resource "aws_iam_policy" "s3_full_access_policy" { 
  name        = "s3_full_access_policy"
  description = "Policy for full S3 access"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action   = "s3:*",
        Effect   = "Allow",
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_full_access_attachment" {
  policy_arn = aws_iam_policy.s3_full_access_policy.arn
  role = aws_iam_role.artifactory-s3-full-access.name
}

// File: main.tf
resource "aws_security_group" "allow_tls_ingress_inline" {
  name        = "allow_tls_ingress_inline"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "something_else" {
  name = "Some_other_sg"
}

resource "aws_security_group_rule" "port_80" {
  type = "ingress"
  protocol = "tcp"
  from_port = 80
  to_port = 80
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.something_else.id
}

resource "aws_security_group_rule" "port_53" {
  type = "ingress"
  protocol = "tcp"
  from_port = 53
  to_port = 53
  cidr_blocks = ["0.0.0.0/0"]
  security_group_id = aws_security_group.something_else.id
}

// File: main.tf
# Get Availability Zones
resource "tls_private_key" "key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "random_pet" "key_prefix" {}

# Create a Key Pair
resource "aws_key_pair" "key_pair" {
  key_name   = "${var.key_prefix}-${random_pet.key_prefix.id}"
  public_key = tls_private_key.key.public_key_openssh

  provisioner "local-exec" {
    command = <<-EOT
      echo "${tls_private_key.key.private_key_pem}" > ../"${var.key_prefix}-${random_pet.key_prefix.id}".pem
      chmod 600 ../"${var.key_prefix}-${random_pet.key_prefix.id}".pem
    EOT
  }
}

// File: outputs.tf
output "key_name" {
  value = aws_key_pair.key_pair.key_name
}

output "key_id" {
  value = aws_key_pair.key_pair.id
}

// File: variables.tf
variable "key_prefix" {
  default = "key"
}

// File: main.tf
resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Act as identifier of this ALB to be used as source security group in other rules. Allows outbound traffic back to origin network"
  vpc_id = var.vpc_id
}

resource "aws_security_group_rule" "alb_ingress_self" {
  type            = "ingress"
  description     = "Allow ALB to communicate with itself (ingress)"
  security_group_id = aws_security_group.alb.id
  protocol        = "tcp"
  from_port       = 0
  to_port         = 65535
  self            = true
}

resource "aws_security_group_rule" "alb_egress_self" {
  type            = "egress"
  description     = "Allow ALB to communicate with itself (egress)"
  security_group_id = aws_security_group.alb.id
  protocol        = "tcp"
  from_port       = 0
  to_port         = 65535
  self            = true
}

resource "aws_security_group" "alb_ecs" {
  name        = "alb-ecs-access"
  description = "Allow ALB access to ECS task(s)"
  vpc_id = var.vpc_id
}

resource "aws_security_group_rule" "alb_ecs_ingress" {
  type            = "ingress"
  description     = "Allow ALB to communicate with ECS tasks on port 8080"
  security_group_id = aws_security_group.alb_ecs.id
  protocol        = "tcp"
  from_port       = 8080
  to_port         = 8080
  source_security_group_id = aws_security_group.alb.id
}

variable "vpc_id" {
  default = "test_vpc"
}

