// File: inputs.tf
# variable for region
variable region {
  type        = string
  default     = "us-west-2"
  description = "target region for creating resources"
}

# vpc range
variable vpc_cidr {
  type        = string
  default     = "192.168.0.0/16"
  description = "cidr range of vpc"
}

# Az's
variable availabilty_zones {
  type        = list(string)
  default     = ["a","b", "c", "a"]
  description = "az's"
}

variable subnet_tags {
  type        = list(string)
  default     = ["web", "app", "db", "mgmt"]
  description = "subnet tags"
}

variable vpctag {
  type        = string
  default     = "from terraform"
  description = "VPC Tag"
}

// File: main.tf
# VPC Section
resource "aws_vpc" "myvpc" {
    cidr_block              = var.vpc_cidr
    enable_dns_support      = true
    tags = {
        Name = var.vpctag
    }
}

# Web Subnet
resource "aws_subnet" "web" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,0)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[0])

    tags = {
        Name = var.subnet_tags[0]
    }

}

resource "aws_subnet" "app" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,1)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[1])

    tags = {
        Name = var.subnet_tags[1]
    }

}

resource "aws_subnet" "db" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,2)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[2])

    tags = {
        Name = var.subnet_tags[2]
    }

}

resource "aws_subnet" "mgmt" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,3)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[3])

    tags = {
        Name = var.subnet_tags[3]
    }

}

// File: providers.tf
provider "aws" {
    region = var.region
}

// File: network.tf
resource "aws_vpc" "elk_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  tags = {
    Name = "ELK VPC"
  }
}

resource "aws_internet_gateway" "elk_gateway" {
  vpc_id = aws_vpc.elk_vpc.id
  tags = {
    Name = "ELK Gateway"
  }
}

resource "aws_route" "public_access" {
  route_table_id         = aws_vpc.elk_vpc.main_route_table_id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.elk_gateway.id
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.elk_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  tags = {
    Name = "Public subnet"
  }
}

resource "aws_eip" "nat_ip" {

}

resource "aws_nat_gateway" "elk_nat" {
  allocation_id = aws_eip.nat_ip.id
  subnet_id     = aws_subnet.public_subnet.id
}

resource "aws_route_table" "elk_route" {
  vpc_id = aws_vpc.elk_vpc.id
  tags = {
    Name = "Private route table"
  }
}

resource "aws_route" "private_access" {
  route_table_id         = aws_route_table.elk_route.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_nat_gateway.elk_nat.id
}

resource "aws_subnet" "private_subnet" {
  vpc_id     = aws_vpc.elk_vpc.id
  cidr_block = "10.0.2.0/24"
  tags = {
    Name = "Private subnet"
  }
}

resource "aws_route_table_association" "public_subnet_association" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_vpc.elk_vpc.main_route_table_id
}

resource "aws_route_table_association" "private_subnet_association" {
  subnet_id      = aws_subnet.private_subnet.id
  route_table_id = aws_route_table.elk_route.id
}

// File: outputs.tf
output "elk_vpc_id" {
  value = aws_vpc.elk_vpc.id
}

output "elk_private_subnet_id" {
  value = aws_subnet.private_subnet.id
}

output "elk_public_subnet_id" {
  value = aws_subnet.public_subnet.id
}

output "elk_private_subnet_cidr" {
  value = aws_subnet.private_subnet.cidr_block
}

output "elk_public_subnet_cidr" {
  value = aws_subnet.public_subnet.cidr_block
}

// File: main.tf
data "aws_region" "current" {}

resource "aws_api_gateway_rest_api" "rest" {
  name = "sns ingest"
}

resource "aws_api_gateway_resource" "ingest" {
  rest_api_id = aws_api_gateway_rest_api.rest.id
  parent_id   = aws_api_gateway_rest_api.rest.root_resource_id
  path_part   = "ingest"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.rest.id
  resource_id   = aws_api_gateway_resource.ingest.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id             = aws_api_gateway_rest_api.rest.id
  resource_id             = aws_api_gateway_resource.ingest.id
  http_method             = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  credentials             = aws_iam_role.sns_publish.arn
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:sns:path//"

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.topic.arn}')&Message=$util.urlEncode($input.body)"
  }
}

resource "aws_api_gateway_method_response" "response_200" {
  rest_api_id = aws_api_gateway_rest_api.rest.id
  resource_id = aws_api_gateway_resource.ingest.id
  http_method = aws_api_gateway_method.method.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "integration_response" {
  rest_api_id = aws_api_gateway_rest_api.rest.id
  resource_id = aws_api_gateway_resource.ingest.id
  http_method = aws_api_gateway_method.method.http_method
  status_code = aws_api_gateway_method_response.response_200.status_code

  depends_on = [aws_api_gateway_integration.integration]

  response_templates = {
    "application/json" = <<EOF
{"status": "message published"}
EOF
  }
}

resource "aws_sns_topic" "topic" {
  name = "event-topic"
}

resource "aws_iam_role" "sns_publish" {
  name               = "sns-publish-role"
  assume_role_policy = data.aws_iam_policy_document.apigw.json
}

data "aws_iam_policy_document" "apigw" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "apigateway.amazonaws.com"
      ]
    }
  }
}

resource "aws_iam_role_policy" "sns_publish" {
  name   = "SNS-Publish"
  role   = aws_iam_role.sns_publish.id
  policy = data.aws_iam_policy_document.sns_publish.json
}

data "aws_iam_policy_document" "sns_publish" {
  statement {
    actions = [
      "sns:Publish",
    ]

    resources = [
      aws_sns_topic.topic.arn
    ]
  }
}

// File: inputs.tf
variable "aws_profile" {
  description = "Name of AWS credentials profile trusted to provision resources as the Role ARN with the AWS Terraform Provider"
  type        = string
  default     = ""
}

variable "aws_region" {
  description = "Name of AWS region to use with the AWS Terraform Provider"
  type        = string
  default     = "us-east-1"
}

// File: main.tf
# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
# CREATE AN S3 BUCKET AND DYNAMODB TABLE TO USE AS A TERRAFORM BACKEND
# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

# ----------------------------------------------------------------------------------------------------------------------
# REQUIRE A SPECIFIC TERRAFORM VERSION OR HIGHER
# This module has been updated with 0.12 syntax, which means it is no longer compatible with any versions below 0.12.
# This module is forked from https://github.com/gruntwork-io/intro-to-terraform/tree/master/s3-backend
# ----------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = ">= 0.12"
}

# ------------------------------------------------------------------------------
# CONFIGURE OUR AWS CONNECTION
# ------------------------------------------------------------------------------

provider "aws" {
  profile = var.aws_profile
  region  = var.aws_region
}

# ------------------------------------------------------------------------------
# CREATE THE S3 BUCKET
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
}

resource "aws_s3_bucket" "terraform_state" {
  # With account id, this S3 bucket names can be *globally* unique.
  bucket = "terraform-states-${local.account_id}-${local.region}"
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# CREATE THE DYNAMODB TABLE
# ------------------------------------------------------------------------------

resource "aws_dynamodb_table" "terraform_lock" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}

// File: outputs.tf
output "s3_bucket_name" {
  value       = aws_s3_bucket.terraform_state.id
  description = "The NAME of the S3 bucket"
}

output "s3_bucket_arn" {
  value       = aws_s3_bucket.terraform_state.arn
  description = "The ARN of the S3 bucket"
}

output "s3_bucket_region" {
  value       = aws_s3_bucket.terraform_state.region
  description = "The REGION of the S3 bucket"
}

output "dynamodb_table_name" {
  value       = aws_dynamodb_table.terraform_lock.name
  description = "The ARN of the DynamoDB table"
}

output "dynamodb_table_arn" {
  value       = aws_dynamodb_table.terraform_lock.arn
  description = "The ARN of the DynamoDB table"
}

// File: default.tf
# default variables

locals {
  default_lifecycle_policy = {
    rules = [{
      rulePriority = 1
      description  = "Only keep 2 images"
      selection = {
        tagStatus   = "any"
        countType   = "imageCountMoreThan"
        countNumber = 2
      }
      action = {
        type = "expire"
      }
    }]
  }
}

// File: labels.tf
# name and description
resource "random_string" "suffix" {
  length  = 5
  upper   = false
  lower   = true
  number  = false
  special = false
}

locals {
  suffix    = random_string.suffix.result
  name      = join("-", compact([var.namespace, (var.name == "" ? local.suffix : var.name)]))
  repo-name = join("/", compact([var.namespace, (var.name == "" ? local.suffix : var.name)]))
  name-tag  = { "Name" = local.repo-name }
  default-tags = merge(
    { "terraform.io" = "managed" },
    local.name-tag
  )
}

// File: main.tf
## managed container image registry service

# security/policy
resource "aws_iam_policy" "read" {
  name        = format("%s-ecr-read", local.name)
  description = format("Allow to read images from the ECR")
  path        = "/"
  policy = jsonencode({
    Statement = [{
      Action = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:BatchGetImage",
        "ecr:DescribeImages",
        "ecr:DescribeRepositories",
        "ecr:GetAuthorizationToken",
        "ecr:GetDownloadUrlForLayer",
        "ecr:ListImages",
      ]
      Effect   = "Allow"
      Resource = [aws_ecr_repository.repo.arn]
    }]
    Version = "2012-10-17"
  })
}

resource "aws_iam_policy" "write" {
  name        = format("%s-ecr-write", local.name)
  description = format("Allow to push and write images to the ECR")
  path        = "/"
  policy = jsonencode({
    Statement = [{
      Action = [
        "ecr:PutImage",
        "ecr:UploadLayerPart",
        "ecr:InitiateLayerUpload",
        "ecr:CompleteLayerUpload",
      ]
      Effect   = "Allow"
      Resource = [aws_ecr_repository.repo.arn]
    }]
    Version = "2012-10-17"
  })
}

data "aws_caller_identity" "current" {}

resource "aws_ecr_repository_policy" "repo" {
  repository = aws_ecr_repository.repo.name
  policy = jsonencode({
    Statement = [{
      Sid = "AllowCrossAccountAccess"
      Action = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:BatchGetImage",
        "ecr:DescribeImages",
        "ecr:DescribeRepositories",
        "ecr:GetAuthorizationToken",
        "ecr:GetDownloadUrlForLayer",
        "ecr:GetRepositoryPolicy",
        "ecr:ListImages",
      ]
      Effect = "Allow"
      Principal = {
        AWS = flatten([
          data.aws_caller_identity.current.account_id,
          var.trusted_accounts,
        ])
      }
    }]
    Version = "2012-10-17"
  })
}

resource "aws_ecr_lifecycle_policy" "repo" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.repo.name
  policy     = var.lifecycle_policy == null ? jsonencode(local.default_lifecycle_policy) : var.lifecycle_policy
}

resource "aws_ecr_repository" "repo" {
  name = local.repo-name
  tags = merge(local.default-tags, var.tags)

  image_tag_mutability = var.image_tag_mutability
  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }
}

// File: outputs.tf
output "name" {
  description = "A name of generated ECR repository"
  value       = aws_ecr_repository.repo.id
}

output "arn" {
  description = "An ARN of generated ECR repository"
  value       = aws_ecr_repository.repo.arn
}

output "url" {
  description = "A URL of generated ECR repository"
  value       = aws_ecr_repository.repo.repository_url
}

output "policy_arns" {
  description = "A map of IAM polices to allow access this ECR repository. If you want to make an IAM role or instance-profile has permissions to manage this repository, please attach the `poliy_arn` of this output on your side."
  value       = zipmap(["read", "write"], [aws_iam_policy.read.arn, aws_iam_policy.write.arn])
}

// File: variables.tf
### security
variable "trusted_accounts" {
  description = "A list of AWS Account IDs you want to allow them access to the ECR repository"
  type        = list(string)
  default     = []
}

variable "image_tag_mutability" {
  description = "The tag mutability setting for the repository. Must be one of: MUTABLE or IMMUTABLE. Defaults to MUTABLE."
  type        = string
  default     = "MUTABLE"
}

variable "scan_on_push" {
  description = "Indicates whether images are scanned after being pushed to the repository (true) or not scanned (false)."
  type        = bool
  default     = false
}

variable "lifecycle_policy" {
  description = "Lifecycle policy JSON document"
  type        = string
  default     = null
}

variable "namespace" {
  description = "Namespace of container image repository"
  type        = string
  default     = ""
}

### description
variable "name" {
  description = "Name of container image repository"
  type        = string
  default     = ""
}

### tags
variable "tags" {
  description = "The key-value maps for tagging"
  type        = map(string)
  default     = {}
}

// File: versions.tf
## requirements

terraform {
  required_version = ">= 0.13"
}

// File: main.tf
provider "aws" {
  region = var.region
}

resource "aws_s3_bucket" "frontend_bucket" {
  bucket = var.frontend_bucket_name
}

resource "aws_s3_bucket_public_access_block" "frontend_bucket_public_access_block" {
  bucket = aws_s3_bucket.frontend_bucket.id

  block_public_acls  = false
  ignore_public_acls = true
}

resource "aws_s3_bucket_policy" "frontend_bucket_policy" {
  bucket = aws_s3_bucket.frontend_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.frontend_bucket.arn}/*"
      }
    ]
  })
}

# Updated CORS configuration for the S3 bucket to include POST
resource "aws_s3_bucket_cors_configuration" "frontend_bucket_cors" {
  bucket = aws_s3_bucket.frontend_bucket.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "HEAD", "PUT", "POST"] # Include POST
    allowed_origins = ["*"]
    expose_headers  = []
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_website_configuration" "frontend_website_config" {
  bucket = aws_s3_bucket.frontend_bucket.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "error.html"
  }
}

resource "aws_cloudfront_response_headers_policy" "cors_policy" {
  name = "frontend-cors-policy"

  cors_config {
    access_control_allow_credentials = false

    access_control_allow_headers {
      items = ["*"]
    }

    access_control_allow_methods {
      items = ["GET", "HEAD", "OPTIONS", "PUT", "POST"] # Include POST
    }

    access_control_allow_origins {
      items = ["*"]
    }

    access_control_expose_headers {
      items = ["*"]
    }

    access_control_max_age_sec = 600
    origin_override            = true
  }

  security_headers_config {
    content_security_policy {
      override                = true
      content_security_policy = "default-src 'self'; connect-src 'self' https://*.execute-api.us-east-1.amazonaws.com; img-src 'self'; script-src 'self'; style-src 'self';"
    }
    content_type_options {
      override = true
    }
    frame_options {
      frame_option = "DENY"
      override     = true
    }
    referrer_policy {
      referrer_policy = "no-referrer"
      override        = true
    }
    strict_transport_security {
      access_control_max_age_sec = 31536000
      include_subdomains         = true
      preload                    = true
      override                   = true
    }
    xss_protection {
      protection = true
      mode_block = true
      override   = true
    }
  }
}

# Attach the policy to the CloudFront distribution
resource "aws_cloudfront_distribution" "frontend_distribution" {
  origin {
    domain_name = aws_s3_bucket.frontend_bucket.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.frontend_bucket.bucket}"
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "CloudFront distribution for frontend"
  default_root_object = "index.html"

  default_cache_behavior {
    allowed_methods  = ["HEAD", "DELETE", "POST", "GET", "OPTIONS", "PUT", "PATCH"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3-${aws_s3_bucket.frontend_bucket.bucket}"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400

    response_headers_policy_id = aws_cloudfront_response_headers_policy.cors_policy.id
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}
#resource "null_resource" "run_setup_script" {
  #provisioner "local-exec" {
    #command = "../../scripts/get-cloudfront-output.sh"
  #}
#
  ## To ensure this runs after apply
  #depends_on = [
    #aws_cloudfront_distribution.frontend_distribution
  #]
#}

// File: outputs.tf
output "frontend_bucket_name" {
  value = aws_s3_bucket.frontend_bucket.bucket
}
output "cloudfront_distribution_domain_name" {
  value = aws_cloudfront_distribution.frontend_distribution.domain_name
}
output "cloudfront_distribution_id" {
  description = "The ID of the CloudFront distribution"
  value       = aws_cloudfront_distribution.frontend_distribution.id
}

// File: variables.tf
variable "region" {
  description = "AWS Region"
  default     = "us-east-1"
}

variable "frontend_bucket_name" {
  description = "Name of the S3 bucket for frontend hosting"
  default     = "dms-frontend-bucket"
}

// File: main.tf
provider "aws" {
  region = local.region
}

data "aws_availability_zones" "available" {}

locals {
  cluster_name = format("%s-%s", basename(path.cwd), "shared")
  region       = "eu-west-1"

  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 3)

  tags = {
    Blueprint  = local.cluster_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

################################################################################
# VPC
################################################################################

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.cluster_name
  cidr = local.vpc_cidr

  azs             = local.azs
  private_subnets = [for k, v in local.azs : cidrsubnet(local.vpc_cidr, 4, k)]
  public_subnets  = [for k, v in local.azs : cidrsubnet(local.vpc_cidr, 8, k + 48)]

  enable_nat_gateway = true
  single_nat_gateway = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = 1
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = 1
  }

  tags = local.tags
}

################################################################################
# Cluster 1 additional security group for cross cluster communication
################################################################################

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Allow communication from cluster2 SG to cluster1 SG"
  vpc_id      = module.vpc.vpc_id
  tags = {
    Name = "cluster1_additional_sg"
  }
}

resource "aws_vpc_security_group_egress_rule" "cluster1_additional_sg_allow_all_4" {
  security_group_id = aws_security_group.cluster1_additional_sg.id

  ip_protocol = "-1"
  cidr_ipv4   = "0.0.0.0/0"
}

resource "aws_vpc_security_group_egress_rule" "cluster1_additional_sg_allow_all_6" {
  security_group_id = aws_security_group.cluster1_additional_sg.id

  ip_protocol = "-1"
  cidr_ipv6   = "::/0"
}

################################################################################
# Cluster 2 additional security group for cross cluster communication
################################################################################

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Allow communication from cluster1 SG to cluster2 SG"
  vpc_id      = module.vpc.vpc_id
  tags = {
    Name = "cluster2_additional_sg"
  }
}

resource "aws_vpc_security_group_egress_rule" "cluster2_additional_sg_allow_all_4" {
  security_group_id = aws_security_group.cluster2_additional_sg.id

  ip_protocol = "-1"
  cidr_ipv4   = "0.0.0.0/0"
}
resource "aws_vpc_security_group_egress_rule" "cluster2_additional_sg_allow_all_6" {
  security_group_id = aws_security_group.cluster2_additional_sg.id

  ip_protocol = "-1"
  cidr_ipv6   = "::/0"
}

################################################################################
# cross SG  ingress rules Cluster 2 allow to cluster 1
################################################################################

resource "aws_vpc_security_group_ingress_rule" "cluster2_to_cluster_1" {
  security_group_id = aws_security_group.cluster1_additional_sg.id

  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

################################################################################
# cross SG  ingress rules Cluster 1 allow to cluster 2
################################################################################

resource "aws_vpc_security_group_ingress_rule" "cluster1_to_cluster_2" {
  security_group_id = aws_security_group.cluster2_additional_sg.id

  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

// File: outputs.tf
output "vpc_id" {
  description = "Amazon EKS VPC ID"
  value       = module.vpc.vpc_id
}

output "subnet_ids" {
  description = "Amazon EKS Subnet IDs"
  value       = module.vpc.private_subnets
}

output "vpc_cidr" {
  description = "Amazon EKS VPC CIDR Block."
  value       = local.vpc_cidr
}

output "cluster1_additional_sg_id" {
  description = "Cluster1 additional SG"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "Cluster2 additional SG"
  value       = aws_security_group.cluster2_additional_sg.id
}

// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.47"
    }
  }

  # ##  Used for end-to-end testing on project; update to suit your needs
  # backend "s3" {
  #   bucket = "<BUCKET_NAME>"
  #   region = "<AWS_REGION>"
  #   key    = "e2e/istio-multi-cluster-vpc/terraform.tfstate"
  # }
}

// File: main.tf
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

data "aws_iam_policy_document" "assume_role" {
  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_admin_role ? [1] : []

    content {
      sid     = "ExplicitSelfAdminRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.admin_role_path}${var.admin_role_name}"]
      }
    }
  }

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_poweruser_role ? [1] : []

    content {
      sid     = "ExplicitSelfPowerUserRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.poweruser_role_path}${var.poweruser_role_name}"]
      }
    }
  }

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_readonly_role ? [1] : []

    content {
      sid     = "ExplicitSelfReadOnlyRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.readonly_role_path}${var.readonly_role_name}"]
      }
    }
  }

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = var.trusted_role_arns
    }

    principals {
      type        = "Service"
      identifiers = var.trusted_role_services
    }
  }
}

data "aws_iam_policy_document" "assume_role_with_mfa" {
  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_admin_role ? [1] : []

    content {
      sid     = "ExplicitSelfAdminRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.admin_role_path}${var.admin_role_name}"]
      }
    }
  }

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_poweruser_role ? [1] : []

    content {
      sid     = "ExplicitSelfPowerUserRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.poweruser_role_path}${var.poweruser_role_name}"]
      }
    }
  }

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_readonly_role ? [1] : []

    content {
      sid     = "ExplicitSelfReadOnlyRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.readonly_role_path}${var.readonly_role_name}"]
      }
    }
  }

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = var.trusted_role_arns
    }

    principals {
      type        = "Service"
      identifiers = var.trusted_role_services
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }

    condition {
      test     = "NumericLessThan"
      variable = "aws:MultiFactorAuthAge"
      values   = [var.mfa_age]
    }
  }
}

# Admin
resource "aws_iam_role" "admin" {
  count = var.create_admin_role ? 1 : 0

  name                 = var.admin_role_name
  path                 = var.admin_role_path
  max_session_duration = var.max_session_duration

  force_detach_policies = var.force_detach_policies
  permissions_boundary  = var.admin_role_permissions_boundary_arn

  assume_role_policy = var.admin_role_requires_mfa ? data.aws_iam_policy_document.assume_role_with_mfa.json : data.aws_iam_policy_document.assume_role.json

  tags = var.admin_role_tags
}

resource "aws_iam_role_policy_attachment" "admin" {
  count = var.create_admin_role ? length(var.admin_role_policy_arns) : 0

  role       = aws_iam_role.admin[0].name
  policy_arn = element(var.admin_role_policy_arns, count.index)
}

# Poweruser
resource "aws_iam_role" "poweruser" {
  count = var.create_poweruser_role ? 1 : 0

  name                 = var.poweruser_role_name
  path                 = var.poweruser_role_path
  max_session_duration = var.max_session_duration

  force_detach_policies = var.force_detach_policies
  permissions_boundary  = var.poweruser_role_permissions_boundary_arn

  assume_role_policy = var.poweruser_role_requires_mfa ? data.aws_iam_policy_document.assume_role_with_mfa.json : data.aws_iam_policy_document.assume_role.json

  tags = var.poweruser_role_tags
}

resource "aws_iam_role_policy_attachment" "poweruser" {
  count = var.create_poweruser_role ? length(var.poweruser_role_policy_arns) : 0

  role       = aws_iam_role.poweruser[0].name
  policy_arn = element(var.poweruser_role_policy_arns, count.index)
}

# Readonly
resource "aws_iam_role" "readonly" {
  count = var.create_readonly_role ? 1 : 0

  name                 = var.readonly_role_name
  path                 = var.readonly_role_path
  max_session_duration = var.max_session_duration

  force_detach_policies = var.force_detach_policies
  permissions_boundary  = var.readonly_role_permissions_boundary_arn

  assume_role_policy = var.readonly_role_requires_mfa ? data.aws_iam_policy_document.assume_role_with_mfa.json : data.aws_iam_policy_document.assume_role.json

  tags = var.readonly_role_tags
}

resource "aws_iam_role_policy_attachment" "readonly" {
  count = var.create_readonly_role ? length(var.readonly_role_policy_arns) : 0

  role       = aws_iam_role.readonly[0].name
  policy_arn = element(var.readonly_role_policy_arns, count.index)
}

