// File: fp5-NonExploitableConditionConstraint.tf
data "aws_iam_policy_document" "fp5-NonExploitableConditionConstraint" {

  statement {

    actions = [
      "iam:CreatePolicyVersion",
    ]

    effect = "Allow"

    resources = [
      "*",
    ]

    condition {
      test     = "DateLessThan"
      variable = "aws:TokenIssueTime"
      values = [
        "2020-01-01T00:00:01Z"
      ]
    }
  }
}





