// File: privesc-permissive-role-trust.tf
# This is a role that does not have any policies attached, but it demonstrates a bad practice. You should never trust the root of an account. That means that anyone who can assume any role can automatically assume this role. You shoul always limit who can assume the role using the principal of least privilege. 

resource "aws_iam_role" "privesc-permissive-role-trust" {
  name                = "privesc-permissive-role-trust"
  assume_role_policy  = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          AWS = var.aws_root_user
        }
      },
    ]
  })
}

// File: variables.tf
variable "aws_local_profile" {
  description = "What local profile should terraform use to interact with your AWS account(s)"
  type        = string
  default     = "default"
}

variable "aws_local_creds_file" {
  description = "Location of your local credentials file"
  type        = string
  default     = "~/.aws/credentials"
}

variable "aws_assume_role_arn" {
  description = "This is the arn of an already existing principal that can assume into any roles that are created"
  type        = string
  default     = ""
}

variable "aws_root_user" {
  description = "This is the root user of the calling account"
  type        = string
  default     = ""
}

// File: appautoscaling.tf
resource "aws_appautoscaling_target" "this" {
  max_capacity       = var.max_capacity
  min_capacity       = var.min_capacity
  resource_id        = "service/${aws_ecs_cluster.this.name}/${aws_ecs_service.this.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

resource "aws_appautoscaling_policy" "this" {
  name               = local.id
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.this.resource_id
  scalable_dimension = aws_appautoscaling_target.this.scalable_dimension
  service_namespace  = aws_appautoscaling_target.this.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value       = var.target_value
    scale_in_cooldown  = var.scale_in_cooldown
    scale_out_cooldown = var.scale_out_cooldown

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
  }
}

// File: cloudwatch.tf
resource "aws_cloudwatch_log_group" "this" {
  name              = local.id
  retention_in_days = var.retention_in_days

  lifecycle {
    ignore_changes = [name]
  }
}

// File: cluster.tf
resource "aws_ecs_cluster" "this" {
  name = local.id

  setting {
    name  = "containerInsights"
    value = var.container_insights_enabled ? "enabled" : "disabled"
  }

  lifecycle {
    ignore_changes = [name]
  }
}

resource "aws_ecs_cluster_capacity_providers" "this" {
  cluster_name       = aws_ecs_cluster.this.name
  capacity_providers = ["FARGATE"]

  default_capacity_provider_strategy {
    capacity_provider = "FARGATE"
    base              = 1
    weight            = 100
  }
}

// File: iam.tf
resource "aws_iam_role" "this" {
  name               = local.id
  assume_role_policy = data.aws_iam_policy_document.assume.json
  tags               = local.tags

  lifecycle {
    ignore_changes = [name]
  }
}

data "aws_iam_policy_document" "assume" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "ecs-tasks.amazonaws.com"
      ]
    }
  }
}

data "aws_iam_policy_document" "ssmmessages" {
  statement {
    actions = [
      "ssmmessages:CreateControlChannel",
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenControlChannel",
      "ssmmessages:OpenDataChannel"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ssmmessages" {
  name   = local.id
  policy = data.aws_iam_policy_document.ssmmessages.json
}

resource "aws_iam_role_policy_attachment" "ssmmessages" {
  policy_arn = aws_iam_policy.ssmmessages.arn
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "ecs" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "ssm" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMReadOnlyAccess"
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "ecr" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "ses" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSESFullAccess"
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "s3" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "lambda" {
  policy_arn = "arn:aws:iam::aws:policy/AWSLambda_FullAccess"
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "textract" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonTextractFullAccess"
  role       = aws_iam_role.this.name
}

// File: lb.tf
resource "aws_lb_target_group" "this" {
  count                = var.lb_enabled ? 1 : 0
  name                 = substr(local.id, 0, 32) # AWS-defined 32 character limit
  port                 = var.port
  protocol             = "HTTP"
  vpc_id               = data.aws_vpcs.this.ids[0]
  target_type          = "ip"
  deregistration_delay = var.deregistration_delay
  tags                 = local.tags

  health_check {
    path                = var.health_check_path
    matcher             = var.matcher
    healthy_threshold   = var.healthy_threshold
    unhealthy_threshold = var.unhealthy_threshold
    interval            = var.interval
    timeout             = var.timeout
  }

  dynamic "stickiness" {
    for_each = var.stickiness != null ? var.stickiness : []
    content {
      enabled         = stickiness.value.enabled
      type            = stickiness.value.type
      cookie_name     = try(stickiness.value.cookie_name, null)
      cookie_duration = stickiness.value.cookie_duration
    }
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_listener_rule" "this" {
  count        = var.lb_enabled ? 1 : 0
  depends_on   = [aws_lb_target_group.this]
  listener_arn = data.aws_lb_listener.this[0].arn
  tags         = local.tags

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this[0].arn
  }

  condition {
    host_header {
      values = ["${var.name}.${var.domain}", "${local.id}.${var.domain}", "${var.host}.${var.domain}"]
    }
  }

  dynamic "condition" {
    for_each = var.source_ips != null ? [""] : []

    content {
      source_ip {
        values = var.source_ips
      }
    }
  }
}

// File: main.tf
locals {
  id          = "${local.name}-${random_string.this.result}"
  name        = var.name == null ? local.image_name : var.name
  tags        = merge(var.tags, { Name = local.id })
  image_repo  = replace(var.image, "/:.*/", "")
  image_name  = replace(local.image_repo, "/.*//", "")
  vpc_found   = length(data.aws_vpcs.this.ids) > 0
  vpc_id      = local.vpc_found ? data.aws_vpcs.this.ids[0] : aws_vpc.this[0].id
  subnets     = local.vpc_found ? data.aws_subnets.this[0].ids : aws_subnet.this[*].id
  environment = merge(var.environment, { SECRETS_SHA = sha256(jsonencode(var.secrets)) })
}

resource "random_string" "this" {
  length  = 8
  special = false
  upper   = false

  lifecycle {
    ignore_changes = [length, special, upper]
  }
}

data "aws_vpcs" "this" {
  tags = var.vpc_tags
}

resource "aws_vpc" "this" {
  count      = local.vpc_found ? 0 : 1
  cidr_block = "10.0.0.0/16"
  tags       = local.tags
}

resource "aws_route" "this" {
  count                  = local.vpc_found ? 0 : 1
  route_table_id         = aws_vpc.this[0].default_route_table_id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_internet_gateway" "this" {
  count  = local.vpc_found ? 0 : 1
  vpc_id = aws_vpc.this[0].id
  tags   = local.tags
}

data "aws_subnets" "this" {
  count = local.vpc_found ? 0 : 1
  tags  = var.subnet_tags

  filter {
    name   = "vpc-id"
    values = [local.vpc_id]
  }
}

resource "aws_subnet" "this" {
  count      = local.vpc_found ? 0 : 2
  vpc_id     = local.vpc_id
  cidr_block = "10.0.${count.index}.0/24"
  tags       = local.tags
}

data "aws_security_groups" "this" {
  count = var.lb_enabled ? 1 : 0
  tags  = var.sg_tags

  filter {
    name   = "vpc-id"
    values = [data.aws_vpcs.this.ids[0]]
  }
}

data "aws_lb" "this" {
  count = var.lb_enabled ? 1 : 0
  tags  = var.lb_tags
}

data "aws_lb_listener" "this" {
  count             = var.lb_enabled ? 1 : 0
  load_balancer_arn = data.aws_lb.this[0].arn
  port              = var.listener_port
}

data "aws_region" "this" {}

// File: outputs.tf
output "id" {
  description = "Name after being processed into a random ID"
  value       = local.id
}

// File: security.tf
resource "aws_security_group" "this" {
  name   = local.id
  vpc_id = local.vpc_id
  tags   = local.tags
}

resource "aws_security_group_rule" "egress" {
  description       = "internet"
  type              = "egress"
  from_port         = 0
  to_port           = 65535
  protocol          = "all"
  security_group_id = aws_security_group.this.id
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "ingress" {
  count                    = var.lb_enabled ? 1 : 0
  description              = "alb"
  type                     = "ingress"
  from_port                = var.port
  to_port                  = var.port
  protocol                 = "tcp"
  security_group_id        = aws_security_group.this.id
  source_security_group_id = data.aws_security_groups.this[0].ids[0]
}

// File: service.tf
locals {
  container = {
    name         = "this"
    environment  = [for key, value in local.environment : { name = key, value = value }]
    essential    = true
    image        = var.image
    command      = var.command
    portMappings = [{ containerPort = var.port }]

    secrets = [
      for parameter in aws_ssm_parameter.this : {
        name = replace(parameter.name, "/.*//", ""), valueFrom = parameter.name
      }
    ]

    logConfiguration = {
      logDriver = "awslogs"

      options = {
        awslogs-group         = aws_cloudwatch_log_group.this.name
        awslogs-region        = data.aws_region.this.name
        awslogs-stream-prefix = "fargate"
      }
    }
  }
}

resource "aws_ecs_task_definition" "this" {
  family                   = local.id
  container_definitions    = jsonencode([local.container])
  cpu                      = var.cpu
  memory                   = var.memory
  execution_role_arn       = aws_iam_role.this.arn
  task_role_arn            = aws_iam_role.this.arn
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  tags                     = local.tags
}

resource "aws_ecs_service" "this" {
  name                              = local.name
  cluster                           = aws_ecs_cluster.this.arn
  depends_on                        = [aws_lb_listener_rule.this]
  desired_count                     = var.min_capacity
  health_check_grace_period_seconds = var.lb_enabled ? var.health_check_grace_period_seconds : null
  launch_type                       = "FARGATE"
  propagate_tags                    = "SERVICE"
  task_definition                   = aws_ecs_task_definition.this.arn
  wait_for_steady_state             = var.wait_for_steady_state
  enable_execute_command            = var.enable_execute_command
  tags                              = local.tags

  network_configuration {
    subnets          = local.subnets
    security_groups  = [aws_security_group.this.id]
    assign_public_ip = var.assign_public_ip
  }

  dynamic "load_balancer" {
    for_each = var.lb_enabled ? [""] : []

    content {
      target_group_arn = aws_lb_target_group.this[0].id
      container_name   = local.container.name
      container_port   = var.port
    }
  }

  lifecycle {
    ignore_changes = [desired_count]
  }
}

// File: ssm.tf
data "aws_kms_secrets" "this" {
  for_each = var.secrets

  secret {
    name    = each.key
    payload = each.value
  }
}

resource "aws_ssm_parameter" "this" {
  for_each = data.aws_kms_secrets.this
  name     = "/fargate/${local.id}/${each.key}"
  type     = "SecureString"
  value    = each.value.plaintext[each.key]
}

// File: variables.tf
variable "name" {
  description = "Unique identifier to be applied to all resources"
  type        = string
  default     = null
}

variable "tags" {
  description = "Map of tags to be applied to all resources"
  type        = map(string)
  default     = {}
}

variable "wait_for_steady_state" {
  description = "https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ecs_service#wait_for_steady_state"
  type        = bool
  default     = true
}

variable "port" {
  description = "Port number of the service running inside your container"
  type        = number
  default     = 80
}

variable "enable_execute_command" {
  description = "https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ecs_service#enable_execute_command"
  type        = bool
  default     = false
}

variable "image" {
  description = "https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task_definition_parameters.html#container_definition_image"
  type        = string
  default     = "httpd"
}

variable "cpu" {
  description = "https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-cpu-memory-error.html"
  type        = number
  default     = 256
}

variable "memory" {
  description = "https://docs.aws.amazon.com/AmazonECS/latest/developerguide/task-cpu-memory-error.html"
  type        = number
  default     = 512
}

variable "assign_public_ip" {
  description = "https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ecs_service#assign_public_ip"
  type        = bool
  default     = true
}

variable "container_insights_enabled" {
  description = "https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ecs_cluster#value"
  type        = bool
  default     = false
}

variable "environment" {
  description = "Map of configuration values to be converted into ECS native format"
  type        = map(string)
  default     = {}
}

variable "secrets" {
  description = "https://docs.aws.amazon.com/AmazonECS/latest/developerguide/specifying-sensitive-data-parameters.html#secrets-envvar-parameters"
  type        = map(string)
  default     = {}
}

